interface Cover { a: string; b: string }

@Component
export struct CoverflowFb {
  @Link step: number

  private covers: Cover[] = [
    { a: '#6366F1', b: '#8B5CF6' },
    { a: '#EC4899', b: '#F43F5E' },
    { a: '#F59E0B', b: '#EF4444' },
    { a: '#10B981', b: '#14B8A6' },
    { a: '#3B82F6', b: '#06B6D4' },
    { a: '#8B5CF6', b: '#D946EF' },
    { a: '#0EA5E9', b: '#22D3EE' },
  ]
  private N: number = 7

  private focusF(): number {
    return this.step / 5
  }

  private dist(i: number): number {
    let d: number = i - this.focusF()
    while (d > this.N / 2) { d -= this.N }
    while (d < -this.N / 2) { d += this.N }
    return d
  }

  private clampD(i: number): number {
    const d: number = this.dist(i)
    return d > 1 ? 1 : (d < -1 ? -1 : d)
  }

  private absD(i: number): number {
    const d: number = this.dist(i)
    return d < 0 ? -d : d
  }

  private scl(i: number): number {
    const a: number = this.absD(i)
    const s: number = 1 - (a > 3 ? 3 : a) * 0.13
    return s
  }

  private opc(i: number): number {
    const a: number = this.absD(i)
    const o: number = 1 - (a > 3 ? 3 : a) * 0.26
    return o < 0.1 ? 0.1 : o
  }

  @Builder
  cover(c: Cover, i: number) {
    Column() {
      Column() {
        Text('♪').fontSize(58).fontColor('#FFFFFF').opacity(0.85)
      }
      .width(250).height(250).borderRadius(22).justifyContent(FlexAlign.Center)
      .linearGradient({ angle: 135, colors: [[c.a, 0], [c.b, 1]] })
      .shadow({ radius: 40, color: '#55000000', offsetY: 20 })
      // reflection
      Column()
        .width(250).height(70).borderRadius(22).margin({ top: 6 })
        .linearGradient({ angle: 90, colors: [[c.b, 0], ['#00000000', 1]] })
        .opacity(0.22)
    }
    .translate({ x: this.dist(i) * 165 })
    .rotate({ y: 1, angle: -this.clampD(i) * 42, perspective: 900 })
    .scale({ x: this.scl(i), y: this.scl(i) })
    .opacity(this.opc(i))
    .zIndex(Math.round(100 - this.absD(i) * 10))
  }

  build() {
    Stack() {
      Column().width('100%').height('100%')
        .linearGradient({ angle: 160, colors: [['#0B1020', 0], ['#1E1B4B', 0.5], ['#0F172A', 1]] })

      Column() {
        // title bar
        Row() {
          Row({ space: 9 }) {
            Circle({ width: 15, height: 15 }).fill('#FF5F57')
            Circle({ width: 15, height: 15 }).fill('#FEBC2E')
            Circle({ width: 15, height: 15 }).fill('#28C840')
          }
          Blank()
          Text('gallery — arkui').fontSize(18).fontColor('#94A3B8')
          Blank()
          Row({ space: 9 }) {
            Circle({ width: 15, height: 15 }).fill('#3A3A52')
            Circle({ width: 15, height: 15 }).fill('#3A3A52')
            Circle({ width: 15, height: 15 }).fill('#3A3A52')
          }
        }
        .width('100%').height(52).padding({ left: 22, right: 22 })
        .backgroundColor('#161B2E').border({ width: { bottom: 1 }, color: '#252542' })

        Stack() {
