interface MI { label: string; keys: string; kind: number } // kind: 0 normal, 1 divider, 2 submenu

@Component
export struct TextMenuFb {
  @Link step: number

  private items: MI[] = [
    { label: 'Copy', keys: '⌘C', kind: 0 },
    { label: 'Look Up', keys: '', kind: 0 },
    { label: 'Translate', keys: '', kind: 0 },
    { label: 'Highlight', keys: '▸', kind: 2 },
    { label: '', keys: '', kind: 1 },
    { label: 'Share', keys: '↗', kind: 0 },
  ]
  private hlColors: string[] = ['#FDE047', '#86EFAC', '#93C5FD', '#F9A8D4']

  private selectable(): number[] {
    const out: number[] = []
    this.items.forEach((m: MI, i: number) => { if (m.kind !== 1) out.push(i) })
    return out
  }

  private active(): number {
    const s: number[] = this.selectable()
    return s[Math.floor(this.step / 4) % s.length]
  }

  private submenuOpen(): boolean {
    return this.items[this.active()].kind === 2
  }

  @Builder
  paraLine(w: number, sel: boolean) {
    if (sel) {
      Row().width(w).height(16).borderRadius(4).backgroundColor('#3B82F6').opacity(0.28)
    } else {
      Row().width(w).height(13).borderRadius(6).backgroundColor('#E2E8F0')
    }
  }

  @Builder
  menuRow(m: MI, idx: number) {
    if (m.kind === 1) {
      Row().width('100%').height(1).backgroundColor('#EEF1F5').margin({ top: 6, bottom: 6 })
    } else {
      Row() {
        Text(m.label).fontSize(20).fontWeight(FontWeight.Medium)
          .fontColor(idx === this.active() ? '#FFFFFF' : '#0F172A')
        Blank()
        Text(m.keys).fontSize(17).fontColor(idx === this.active() ? '#E0E7FF' : '#94A3B8')
      }
      .width('100%').height(44).padding({ left: 14, right: 14 }).borderRadius(9)
      .backgroundColor(idx === this.active() ? '#6366F1' : '#00000000')
    }
  }

  build() {
    Stack() {
      Column().width('100%').height('100%')
