        // title bar
        Row() {
          Row({ space: 9 }) {
            Circle({ width: 15, height: 15 }).fill('#FF5F57')
            Circle({ width: 15, height: 15 }).fill('#FEBC2E')
            Circle({ width: 15, height: 15 }).fill('#28C840')
          }
          Blank()
          Text('document — arkui').fontSize(18).fontColor('#94A3B8')
          Blank()
          Row({ space: 9 }) {
            Circle({ width: 15, height: 15 }).fill('#E2E8F0')
            Circle({ width: 15, height: 15 }).fill('#E2E8F0')
            Circle({ width: 15, height: 15 }).fill('#E2E8F0')
          }
        }
        .width('100%').height(52).padding({ left: 22, right: 22 })
        .backgroundColor('#F8FAFC').border({ width: { bottom: 1 }, color: '#E2E8F0' })

        Stack({ alignContent: Alignment.TopStart }) {
          // document
          Column() {
            Row().width(420).height(26).borderRadius(6).backgroundColor('#CBD5E1').margin({ bottom: 24 })
            Column({ space: 18 }) {
              this.paraLine(720, false)
              this.paraLine(680, false)
              this.paraLine(700, true)
              this.paraLine(640, false)
              this.paraLine(710, false)
              this.paraLine(560, false)
            }.alignItems(HorizontalAlign.Start)
            Column({ space: 18 }) {
              this.paraLine(700, false)
              this.paraLine(660, false)
              this.paraLine(690, false)
              this.paraLine(500, false)
            }.alignItems(HorizontalAlign.Start).margin({ top: 30 })
          }
          .width('100%').height('100%').padding({ left: 60, top: 46 })
          .backgroundColor('#FFFFFF').alignItems(HorizontalAlign.Start)

          // selection floating menu group
          Stack({ alignContent: Alignment.TopStart }) {
            Column() {
              ForEach(this.items, (m: MI, i: number) => {
