interface TLine { kind: number; text: string; color: string } // kind: 0 command, 1 output

@Component
export struct TerminalFb {
  @Link step: number

  private lines: TLine[] = [
    { kind: 0, text: 'npm run build', color: '#E6EDF3' },
    { kind: 1, text: '> arkui-app@1.0.0 build', color: '#8B949E' },
    { kind: 1, text: '✓ compiled successfully in 3.24s', color: '#3FB950' },
    { kind: 0, text: 'git status', color: '#E6EDF3' },
    { kind: 1, text: 'On branch main', color: '#8B949E' },
    { kind: 1, text: "nothing to commit, working tree clean", color: '#8B949E' },
    { kind: 0, text: 'ohpm install', color: '#E6EDF3' },
    { kind: 1, text: 'Resolving dependencies…', color: '#8B949E' },
    { kind: 1, text: '✓ 42 packages installed in 1.8s', color: '#3FB950' },
  ]

  private cycle(): number {
    return this.lines.length * 2 + 8
  }

  private shown(): number {
    const p: number = this.step % this.cycle()
    return Math.min(this.lines.length, Math.floor(p / 2))
  }

  @Builder
  line(l: TLine) {
    if (l.kind === 0) {
      Row() {
        Text('➜').fontSize(20).fontColor('#3FB950').fontWeight(FontWeight.Bold)
        Text(' ~/arkui').fontSize(20).fontColor('#58A6FF').fontFamily('Courier New')
        Text(' ' + l.text).fontSize(20).fontColor(l.color).fontFamily('Courier New')
      }.margin({ bottom: 6 })
    } else {
      Text(l.text).fontSize(20).fontColor(l.color).fontFamily('Courier New').margin({ bottom: 6 })
    }
  }

  build() {
    Stack() {
      Column().width('100%').height('100%')
        .linearGradient({ angle: 135, colors: [['#0F172A', 0], ['#111827', 0.5], ['#1F2937', 1]] })

      Column() {
        // title bar (dark)
        Row() {
          Row({ space: 9 }) {
            Circle({ width: 15, height: 15 }).fill('#FF5F57')
            Circle({ width: 15, height: 15 }).fill('#FEBC2E')
            Circle({ width: 15, height: 15 }).fill('#28C840')
          }
          Blank()
          Text('zsh — arkui').fontSize(18).fontColor('#8B949E')
          Blank()
          Row({ space: 16 }) {
            Text('+').fontSize(22).fontColor('#6E7681')
            Text('⌄').fontSize(20).fontColor('#6E7681')
          }
        }
        .width('100%').height(52).padding({ left: 22, right: 22 })
        .backgroundColor('#161B22').border({ width: { bottom: 1 }, color: '#21262D' })

        // terminal body
        Column() {
          ForEach(this.lines.slice(0, this.shown()), (l: TLine, i: number) => {
            this.line(l)
          }, (l: TLine, i: number) => 'tl' + i + '-' + l.text)
          // prompt + cursor on the current line
          Row() {
            Text('➜').fontSize(20).fontColor('#3FB950').fontWeight(FontWeight.Bold)
            Text(' ~/arkui ').fontSize(20).fontColor('#58A6FF').fontFamily('Courier New')
            Column().width(11).height(22).backgroundColor('#E6EDF3').opacity(this.step % 2 === 0 ? 1 : 0.15)
