}

interface Kpi { label: string; base: number; mod: number; prefix: string; trend: string; color: string }

@Component
export struct DashboardFb {
  @Link step: number

  private kpis: Kpi[] = [
    { label: 'Revenue', base: 84200, mod: 40, prefix: '$', trend: '+12.4%', color: '#6366F1' },
    { label: 'Active Users', base: 12480, mod: 50, prefix: '', trend: '+3.1%', color: '#10B981' },
    { label: 'Orders', base: 1320, mod: 30, prefix: '', trend: '+8.7%', color: '#F59E0B' },
    { label: 'Conversion', base: 348, mod: 12, prefix: '', trend: '-1.2%', color: '#EC4899' },
  ]

  private barH(i: number): number {
    return Math.round(60 + 110 * (0.5 + 0.5 * Math.sin((this.step + i * 1.5) / 2.4)))
  }

  private ringVal(): number {
    return Math.round(58 + 26 * Math.sin(this.step / 3))
  }

  private kpiVal(k: Kpi): string {
    const v: number = k.base + (this.step % k.mod)
    return k.prefix + v.toString()
  }

