interface MI { label: string; keys: string; kind: number } // kind: 0 normal, 1 divider, 2 danger, 3 submenu

@Component
export struct ContextMenuFb {
  @Link step: number

  private items: MI[] = [
    { label: 'Cut', keys: '⌘X', kind: 0 },
    { label: 'Copy', keys: '⌘C', kind: 0 },
    { label: 'Paste', keys: '⌘V', kind: 0 },
    { label: '', keys: '', kind: 1 },
    { label: 'Rename', keys: '↩', kind: 0 },
    { label: 'Duplicate', keys: '⌘D', kind: 0 },
    { label: 'Share', keys: '▸', kind: 3 },
    { label: '', keys: '', kind: 1 },
    { label: 'Delete', keys: '⌫', kind: 2 },
  ]
  private sub: string[] = ['Email', 'Copy Link', 'AirDrop']

  private selectable(): number[] {
    const out: number[] = []
    this.items.forEach((m: MI, i: number) => { if (m.kind !== 1) out.push(i) })
    return out
  }

  private active(): number {
    const s: number[] = this.selectable()
    return s[Math.floor(this.step / 4) % s.length]
  }

  private submenuOpen(): boolean {
    return this.items[this.active()].kind === 3
  }

  @Builder
  menuRow(m: MI, idx: number) {
    if (m.kind === 1) {
      Row().width('100%').height(1).backgroundColor('#EEF1F5').margin({ top: 6, bottom: 6 })
    } else {
      Row() {
        Text(m.label).fontSize(21)
          .fontColor(m.kind === 2 ? '#EF4444' : (idx === this.active() ? '#FFFFFF' : '#0F172A'))
          .fontWeight(FontWeight.Medium)
        Blank()
        Text(m.keys).fontSize(17)
          .fontColor(idx === this.active() ? '#E0E7FF' : '#94A3B8')
      }
      .width('100%').height(46).padding({ left: 14, right: 14 }).borderRadius(9)
      .backgroundColor(idx === this.active() ? (m.kind === 2 ? '#EF4444' : '#6366F1') : '#00000000')
    }
  }

  @Builder
  fileTile(color: string) {
    Column() {
      Column().width(72).height(56).borderRadius(10).backgroundColor(color).opacity(0.85)
      Row().width(60).height(9).borderRadius(4).backgroundColor('#CBD5E1').margin({ top: 12 })
    }.alignItems(HorizontalAlign.Center)
  }

  build() {
    Stack() {
      Column().width('100%').height('100%')
