          Row({ space: 9 }) {
            Circle({ width: 15, height: 15 }).fill('#E2E8F0')
            Circle({ width: 15, height: 15 }).fill('#E2E8F0')
            Circle({ width: 15, height: 15 }).fill('#E2E8F0')
          }
        }
        .width('100%').height(52).padding({ left: 22, right: 22 })
        .backgroundColor('#F8FAFC').border({ width: { bottom: 1 }, color: '#E2E8F0' })

        // content: file grid + context menu
