                  }.width('100%').height(44).padding({ left: 14, right: 14 }).borderRadius(9)
                  .backgroundColor(i === 0 ? '#6366F1' : '#00000000')
                }, (s: string, i: number) => 'su' + i + s)
              }
              .width(230).padding(8).borderRadius(14)
              .backgroundColor('#FFFFFF').border({ width: 1, color: '#E2E8F0' })
              .shadow({ radius: 60, color: '#44000000', offsetY: 20 })
              .position({ x: 292, y: 268 })
