          }
          .offset({ x: 300, y: 150 })

          // cursor
          Text('▶').fontSize(30).fontColor('#0F172A').rotate({ angle: -45 })
            .position({ x: 300, y: 168 })
        }
        .width('100%').layoutWeight(1)
      }
