interface TR { depth: number; icon: number; color: string; w: number } // icon: 0 folder-open, 1 folder-closed, 2 file

@Component
export struct FileTreeFb {
  @Link step: number

  private rows(): TR[] {
    const srcOpen: boolean = Math.floor(this.step / 8) % 2 === 0
    const list: TR[] = []
    list.push({ depth: 0, icon: srcOpen ? 0 : 1, color: '#F59E0B', w: 70 }) // src
    if (srcOpen) {
      list.push({ depth: 1, icon: 2, color: '#60A5FA', w: 110 })
      list.push({ depth: 1, icon: 2, color: '#60A5FA', w: 90 })
      list.push({ depth: 1, icon: 2, color: '#34D399', w: 130 })
    }
    list.push({ depth: 0, icon: 0, color: '#F59E0B', w: 120 }) // components (open)
    list.push({ depth: 1, icon: 2, color: '#C084FC', w: 100 })
    list.push({ depth: 1, icon: 2, color: '#C084FC', w: 120 })
    list.push({ depth: 0, icon: 1, color: '#F59E0B', w: 80 })  // assets (closed)
    list.push({ depth: 0, icon: 2, color: '#94A3B8', w: 110 }) // README
    list.push({ depth: 0, icon: 2, color: '#94A3B8', w: 130 }) // package.json
    return list
  }

  private sel(): number {
    const n: number = this.rows().length
    return this.step % n
  }

  @Builder
  treeRow(r: TR, idx: number) {
    Row() {
      if (r.depth > 0) { Row().width(28).height(1) }
      if (r.icon !== 2) {
        Text(r.icon === 0 ? '▾' : '▸').fontSize(16).fontColor('#94A3B8').width(22)
      } else {
        Row().width(22).height(1)
      }
      Column().width(22).height(17).borderRadius(4).backgroundColor(r.color)
      Row().width(r.w).height(10).borderRadius(5)
        .backgroundColor(idx === this.sel() ? '#94A3B8' : '#CBD5E1').margin({ left: 12 })
      Blank()
    }
    .width('100%').height(44).padding({ left: 12, right: 12 }).borderRadius(8)
    .backgroundColor(idx === this.sel() ? '#EEF2FF' : '#00000000')
    .border({ width: { left: 3 }, color: idx === this.sel() ? '#6366F1' : '#00000000' })
  }

  build() {
    Stack() {
      Column().width('100%').height('100%')
        .linearGradient({ angle: 135, colors: [['#0F172A', 0], ['#1E293B', 0.5], ['#0F766E', 1]] })

      Column() {
