          }
        }
        .width('100%').height(52).padding({ left: 22, right: 22 })
        .backgroundColor('#F8FAFC').border({ width: { bottom: 1 }, color: '#E2E8F0' })

        Row() {
          // explorer sidebar
          Column() {
            Row() {
              Text('EXPLORER').fontSize(15).fontColor('#94A3B8').fontWeight(FontWeight.Bold)
              Blank()
              Text('⋯').fontSize(20).fontColor('#CBD5E1')
            }.width('100%').margin({ bottom: 14 })
            Row() {
              Text('▾').fontSize(15).fontColor('#64748B').margin({ right: 6 })
              Text('ARKUI-APP').fontSize(15).fontColor('#64748B').fontWeight(FontWeight.Bold)
            }.width('100%').margin({ bottom: 8 }).justifyContent(FlexAlign.Start)
