@Component
export struct WatchWindFb {
  @State private dirDeg: number = 0
  @State private speed: number = 12
  private frames: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.dirDeg = (this.dirDeg + 1) % 360
      this.frames = this.frames + 1
      if (this.frames % 6 === 0) { this.speed = 8 + Math.round(Math.random() * 20) }
    }, 60)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private dirName(): string {
    const dirs: string[] = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']
    return dirs[Math.round(this.dirDeg / 45) % 8]
  }

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Circle().width(206).height(206).fillOpacity(0).stroke('#1E2A3A').strokeWidth(2)
      Text('N').fontSize(15).fontColor('#94A3B8').offset({ x: 0, y: -84 })
      Text('E').fontSize(15).fontColor('#94A3B8').offset({ x: 84, y: 0 })
      Text('S').fontSize(15).fontColor('#94A3B8').offset({ x: 0, y: 84 })
      Text('W').fontSize(15).fontColor('#94A3B8').offset({ x: -84, y: 0 })
      Column() {
        Text('▲').fontSize(30).fontColor('#38BDF8')
      }.width(30).height(180).justifyContent(FlexAlign.Start).rotate({ angle: this.dirDeg })
      Column({ space: 2 }) {
        Text(this.speed + '').fontSize(50).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        Text('km/h').fontSize(14).fontColor('#9CA3AF')
        Text(this.dirName() + ' wind').fontSize(13).fontWeight(FontWeight.Bold).fontColor('#38BDF8')
      }
    }
    .width('100%').height('100%').backgroundColor('#000000')
  }
}

@Component
export struct WatchFocusFb {
  @State private secs: number = 1500
  @State private mode: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.secs -= 5
      if (this.secs <= 0) { this.mode = 1 - this.mode; this.secs = this.mode === 0 ? 1500 : 300 }
    }, 60)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private total(): number { return this.mode === 0 ? 1500 : 300 }
  private pad2(n: number): string { return n < 10 ? '0' + n : '' + n }

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Progress({ value: this.secs / this.total() * 100, total: 100, type: ProgressType.Ring })
        .width(210).height(210).color(this.mode === 0 ? '#EF4444' : '#22C55E')
        .backgroundColor('#1E293B').style({ strokeWidth: 16 })
      Column({ space: 4 }) {
        Text(this.mode === 0 ? '🍅' : '☕').fontSize(32)
        Text(this.pad2(Math.floor(this.secs / 60)) + ':' + this.pad2(this.secs % 60))
          .fontSize(48).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        Text(this.mode === 0 ? 'Focus' : 'Break').fontSize(15).fontWeight(FontWeight.Bold)
          .fontColor(this.mode === 0 ? '#EF4444' : '#22C55E')
      }
    }
    .width('100%').height('100%').backgroundColor('#000000')
  }
}

@Component
export struct WatchCoinFb {
  @State private face: number = 0
  @State private sy: number = 1
  private frames: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.frames = this.frames + 1
      const p: number = this.frames % 20
      if (p < 10) { this.sy = 1 - (p / 10) * 0.88 } else { this.sy = 0.12 + ((p - 10) / 10) * 0.88 }
      if (p === 10) { this.face = 1 - this.face }
    }, 55)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  build() {
    Column({ space: 20 }) {
      Stack({ alignContent: Alignment.Center }) {
        Column().width(120).height(120).borderRadius(60)
          .linearGradient({ angle: 135, colors: [['#FFFDE047', 0], ['#FFF59E0B', 1]] })
          .scale({ y: this.sy })
          .shadow({ radius: 18, color: '#55F59E0B' })
        Text(this.face === 0 ? 'H' : 'T').fontSize(54).fontWeight(FontWeight.Bold).fontColor('#7C4A03')
          .scale({ y: this.sy })
      }.width(140).height(140)
      Text(this.face === 0 ? 'Heads' : 'Tails').fontSize(22).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#000000')
  }
}

