@Component
export struct WatchHourlyFb {
  @State private base: number = 9
  private t: number = -1

  aboutToAppear(): void { this.t = setInterval(() => { this.base = (this.base + 1) % 24 }, 650) }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private iconFor(h: number): string {
    if (h < 6 || h >= 20) { return '🌙' }
    const c: number = h % 4
    if (c === 0) { return '☀️' }
    if (c === 1) { return '⛅' }
    if (c === 2) { return '🌤️' }
    return '☁️'
  }
  private tempFor(h: number): number { return 15 + Math.round(8 * Math.sin((h - 6) / 12 * Math.PI)) }

  @Builder
  Hour(i: number) {
    Column({ space: 4 }) {
      Text((i === 0 ? 'Now' : ((this.base + i) % 24) + 'h')).fontSize(10).fontWeight(FontWeight.Bold)
        .fontColor(i === 0 ? '#0B1220' : '#9CA3AF')
      Text(this.iconFor((this.base + i) % 24)).fontSize(20)
      Text(this.tempFor((this.base + i) % 24) + '°').fontSize(14).fontWeight(FontWeight.Bold)
        .fontColor(i === 0 ? '#0B1220' : '#FFFFFF')
    }.layoutWeight(1).padding({ top: 8, bottom: 8 })
    .backgroundColor(i === 0 ? '#38BDF8' : '#111827').borderRadius(10)
  }

  build() {
    Column({ space: 12 }) {
      Text('🌤 Hourly Forecast').fontSize(13).fontWeight(FontWeight.Bold).fontColor('#9CA3AF')
      Row({ space: 5 }) {
        this.Hour(0)
        this.Hour(1)
        this.Hour(2)
        this.Hour(3)
        this.Hour(4)
      }.width(214)
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#0B1530')
  }
}

@Component
export struct WatchDiceFb {
  @State private d1: number = 3
  @State private d2: number = 5
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.d1 = 1 + Math.floor(Math.random() * 6)
      this.d2 = 1 + Math.floor(Math.random() * 6)
    }, 150)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private isOn(v: number, idx: number): boolean {
    if (v === 1) { return idx === 4 }
    if (v === 2) { return idx === 0 || idx === 8 }
    if (v === 3) { return idx === 0 || idx === 4 || idx === 8 }
    if (v === 4) { return idx === 0 || idx === 2 || idx === 6 || idx === 8 }
    if (v === 5) { return idx === 0 || idx === 2 || idx === 4 || idx === 6 || idx === 8 }
    return idx === 0 || idx === 2 || idx === 3 || idx === 5 || idx === 6 || idx === 8
  }

  @Builder
  Die(which: number) {
    Column({ space: 7 }) {
      ForEach([0, 1, 2], (r: number) => {
        Row({ space: 7 }) {
          ForEach([0, 1, 2], (c: number) => {
            Circle().width(11).height(11)
              .fill(this.isOn(which === 1 ? this.d1 : this.d2, r * 3 + c) ? '#0F172A' : '#00000000')
          }, (c: number) => (r * 3 + c) + (this.isOn(which === 1 ? this.d1 : this.d2, r * 3 + c) ? 'x' : 'o'))
        }
      }, (r: number) => r.toString())
    }
    .width(74).height(74).padding(11).backgroundColor('#FFFFFF').borderRadius(14)
  }

  build() {
    Column({ space: 14 }) {
      Text('🎲 Roll the Dice').fontSize(14).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
      Row({ space: 16 }) {
        this.Die(1)
        this.Die(2)
      }
      Text('Total ' + (this.d1 + this.d2)).fontSize(18).fontWeight(FontWeight.Bold).fontColor('#FBBF24')
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#166534')
  }
}

@Component
export struct WatchPrayerFb {
  @State private remain: number = 4980
  @State private nextIdx: number = 3
  private names: string[] = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha']
  private times: string[] = ['05:12', '13:07', '16:45', '20:31', '22:01']
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.remain -= 5
      if (this.remain <= 0) { this.nextIdx = (this.nextIdx + 1) % 5; this.remain = 3600 + Math.round(Math.random() * 5400) }
    }, 100)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private pad2(n: number): string { return n < 10 ? '0' + n : '' + n }
  private cd(): string {
    return Math.floor(this.remain / 3600) + ':' + this.pad2(Math.floor((this.remain % 3600) / 60)) + ':' + this.pad2(this.remain % 60)
  }

  @Builder
  Pill(i: number) {
    Column({ space: 2 }) {
      Text(this.names[i]).fontSize(9).fontWeight(FontWeight.Bold).fontColor(i === this.nextIdx ? '#052E2B' : '#9CA3AF')
      Text(this.times[i]).fontSize(10).fontWeight(FontWeight.Bold).fontColor(i === this.nextIdx ? '#052E2B' : '#E5E7EB')
    }.padding({ top: 5, bottom: 5, left: 4, right: 4 }).borderRadius(8)
    .backgroundColor(i === this.nextIdx ? '#34D399' : '#111827').layoutWeight(1)
  }

  build() {
    Column({ space: 3 }) {
      Text('🕌 Next Prayer').fontSize(12).fontWeight(FontWeight.Bold).fontColor('#9CA3AF')
      Text(this.names[this.nextIdx]).fontSize(30).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
      Text('in ' + this.cd()).fontSize(18).fontWeight(FontWeight.Bold).fontColor('#34D399')
      Row({ space: 4 }) {
        this.Pill(0)
        this.Pill(1)
        this.Pill(2)
        this.Pill(3)
        this.Pill(4)
      }.width(212).margin({ top: 8 })
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#050810')
  }
}

@Component
export struct WatchLevelFb {
  @State private bx: number = 0
  @State private by: number = 0
  private frames: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.frames = this.frames + 1
      this.bx = 62 * Math.sin(this.frames * 0.05)
      this.by = 62 * Math.sin(this.frames * 0.071)
    }, 45)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private lvl(): boolean { return Math.abs(this.bx) < 12 && Math.abs(this.by) < 12 }

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Circle().width(200).height(200).fillOpacity(0).stroke('#334155').strokeWidth(2)
      Circle().width(60).height(60).fillOpacity(0).stroke(this.lvl() ? '#22C55E' : '#475569').strokeWidth(2)
      Circle().width(46).height(46).fill(this.lvl() ? '#22C55E' : '#38BDF8')
        .opacity(0.85).translate({ x: this.bx, y: this.by })
      Column({ space: 2 }) {
        Text(this.lvl() ? 'LEVEL' : Math.round(Math.abs(this.bx) / 6) + '°').fontSize(15).fontWeight(FontWeight.Bold)
          .fontColor(this.lvl() ? '#22C55E' : '#FFFFFF').offset({ y: 70 })
      }
    }
    .width('100%').height('100%').backgroundColor('#000000')
  }
}

