  private tasks: string[] = ['Morning run', 'Team standup', 'Call mom']
  private t: number = -1

  aboutToAppear(): void { this.t = setInterval(() => { this.done = (this.done + 1) % 4 }, 850) }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  @Builder
  Task(idx: number) {
    Row() {
      Stack({ alignContent: Alignment.Center }) {
        Circle().width(24).height(24)
          .fill(idx < this.done ? '#22C55E' : '#00000000')
          .stroke(idx < this.done ? '#22C55E' : '#4B5563').strokeWidth(2)
        if (idx < this.done) { Text('✓').fontSize(14).fontColor('#FFFFFF') }
      }.width(24).height(24)
      Text(this.tasks[idx]).fontSize(15).fontWeight(FontWeight.Medium)
        .fontColor(idx < this.done ? '#6B7280' : '#FFFFFF')
        .decoration({ type: idx < this.done ? TextDecorationType.LineThrough : TextDecorationType.None })
        .margin({ left: 12 }).layoutWeight(1)
    }.width(198).padding({ top: 9, bottom: 9 })
  }

  build() {
    Column({ space: 2 }) {
      Text('✓ Reminders').fontSize(14).fontWeight(FontWeight.Bold).fontColor('#22C55E').margin({ bottom: 8 })
      this.Task(0)
      this.Task(1)
      this.Task(2)
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#000000')
  }
}

@Component
export struct WatchLiveScoreFb {
  @State private matchMin: number = 1
  @State private home: number = 0
  @State private away: number = 0
  private frames: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.frames = this.frames + 1
      const m: number = this.frames % 95
      if (m === 0) { this.home = 0; this.away = 0 }
      this.matchMin = m > 90 ? 90 : m
      if (this.frames % 33 === 0) { this.home = this.home + 1 }
      if (this.frames % 57 === 0) { this.away = this.away + 1 }
    }, 240)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  build() {
    Column({ space: 12 }) {
      Row({ space: 6 }) {
        Circle().width(8).height(8).fill('#EF4444')
        Text('LIVE ' + this.matchMin + "'").fontSize(13).fontWeight(FontWeight.Bold).fontColor('#EF4444')
      }
      Row() {
        Column({ space: 4 }) {
          Text('🔴').fontSize(26)
          Text('ARS').fontSize(12).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        }.width(60)
        Text(this.home + ' - ' + this.away).fontSize(38).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
          .layoutWeight(1).textAlign(TextAlign.Center).maxLines(1)
        Column({ space: 4 }) {
          Text('🔵').fontSize(26)
          Text('CHE').fontSize(12).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        }.width(60)
      }.width(210)
      Stack({ alignContent: Alignment.Start }) {
        Row().width(190).height(5).borderRadius(3).backgroundColor('#1E2A3A')
        Row().width(this.matchMin / 90 * 190).height(5).borderRadius(3).backgroundColor('#22C55E')
      }.width(190)
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#000000')
  }
}

@Component
export struct WatchVoiceMemoFb {
  @State private bars: number[] = [12, 26, 16, 30, 20, 34, 22, 28, 18]
  @State private on: boolean = true
  @State private frames: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.bars = this.bars.map(() => 6 + Math.round(Math.random() * 34))
      this.on = !this.on
      this.frames = this.frames + 1
    }, 160)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private pad2(n: number): string { return n < 10 ? '0' + n : '' + n }
  private timeStr(): string {
    const total: number = Math.floor(this.frames * 0.16)
    return this.pad2(Math.floor(total / 60)) + ':' + this.pad2(total % 60)
  }

  build() {
    Column({ space: 14 }) {
      Row({ space: 8 }) {
        Circle().width(11).height(11).fill('#EF4444').opacity(this.on ? 1 : 0.25)
        Text('REC').fontSize(13).fontWeight(FontWeight.Bold).fontColor('#EF4444')
        Text(this.timeStr()).fontSize(15).fontWeight(FontWeight.Bold).fontColor('#FFFFFF').margin({ left: 6 })
      }
      Row({ space: 4 }) {
        ForEach(this.bars, (v: number, i: number) => {
          Column().width(8).height(v).borderRadius(4).backgroundColor('#8B5CF6')
        }, (v: number, i: number) => i + '-' + v)
      }.height(42).alignItems(VerticalAlign.Center)
      Text('■').fontSize(16).fontColor('#FFFFFF').width(56).height(56).textAlign(TextAlign.Center)
        .backgroundColor('#EF4444').borderRadius(28)
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#000000')
  }
}

