@Component
export struct WatchSunPathFb {
  @State private p: number = 0
  private dir: number = 0.005
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.p += this.dir
      if (this.p >= 1) { this.p = 1; this.dir = -0.005 }
      else if (this.p <= 0) { this.p = 0; this.dir = 0.005 }
    }, 50)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private arcPts(): number[][] {
    const res: number[][] = []
    for (let i = 0; i <= 22; i++) {
      const t: number = i / 22
      res.push([t * 200, 96 - 88 * Math.sin(t * Math.PI)])
    }
    return res
  }

  build() {
    Column({ space: 10 }) {
      Text('☀️ Daylight').fontSize(14).fontWeight(FontWeight.Bold).fontColor('#FBBF24')
      Stack({ alignContent: Alignment.TopStart }) {
        Polyline().width(200).height(100).points(this.arcPts())
          .fillOpacity(0).stroke('#59FFFFFF').strokeWidth(2).strokeDashArray([5, 5])
        Circle().width(24).height(24).fill('#FFD54A').shadow({ radius: 14, color: '#AAFACC15' })
          .translate({ x: this.p * 200 - 12, y: 96 - 88 * Math.sin(this.p * Math.PI) - 12 })
      }.width(200).height(100)
      Row() {
        Text('🌅 6:24').fontSize(12).fontWeight(FontWeight.Medium).fontColor('#E5E7EB')
        Blank()
        Text('20:36 🌇').fontSize(12).fontWeight(FontWeight.Medium).fontColor('#E5E7EB')
      }.width(200)
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#0B1530')
  }
}

@Component
export struct WatchPayFb {
  @State private wave: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => { this.wave += 0.024; if (this.wave >= 1) { this.wave = 0 } }, 45)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private ph(off: number): number {
    let p: number = this.wave + off
    if (p >= 1) { p -= 1 }
    return p
  }

  build() {
    Column({ space: 16 }) {
      Column({ space: 6 }) {
        Row() {
          Text('💳').fontSize(16)
          Blank()
          Text('VISA').fontSize(12).fontWeight(FontWeight.Bold).fontColor('#FFFFFF').fontStyle(FontStyle.Italic)
        }.width('100%')
        Text('•••• 4242').fontSize(16).fontWeight(FontWeight.Bold).fontColor('#FFFFFF').letterSpacing(1)
      }
      .width(154).padding(13).borderRadius(13)
      .linearGradient({ angle: 135, colors: [['#FF4F46E5', 0], ['#FF7C3AED', 1]] })

      Stack({ alignContent: Alignment.Center }) {
        Circle().width(74).height(74).fillOpacity(0).stroke('#22C55E').strokeWidth(3)
          .scale({ x: 0.45 + this.ph(0) * 0.9, y: 0.45 + this.ph(0) * 0.9 }).opacity(1 - this.ph(0))
        Circle().width(74).height(74).fillOpacity(0).stroke('#22C55E').strokeWidth(3)
          .scale({ x: 0.45 + this.ph(0.33) * 0.9, y: 0.45 + this.ph(0.33) * 0.9 }).opacity(1 - this.ph(0.33))
        Circle().width(74).height(74).fillOpacity(0).stroke('#22C55E').strokeWidth(3)
          .scale({ x: 0.45 + this.ph(0.66) * 0.9, y: 0.45 + this.ph(0.66) * 0.9 }).opacity(1 - this.ph(0.66))
        Circle().width(16).height(16).fill('#22C55E')
      }.width(150).height(90)

      Text('Hold near reader').fontSize(13).fontWeight(FontWeight.Bold).fontColor('#9CA3AF')
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#000000')
  }
}

@Component
export struct WatchAltimeterFb {
  @State private elev: number = 800
  private dir: number = 4
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.elev += this.dir
      if (this.elev >= 2400) { this.elev = 2400; this.dir = -4 }
      else if (this.elev <= 400) { this.elev = 400; this.dir = 4 }
    }, 45)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private fmt(n: number): string {
    const s: string = '' + Math.round(n)
    if (s.length <= 3) { return s }
    return s.slice(0, s.length - 3) + ',' + s.slice(s.length - 3)
  }

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Progress({ value: this.elev / 3000 * 100, total: 100, type: ProgressType.Ring })
        .width(210).height(210).color('#F59E0B').backgroundColor('#2A2010').style({ strokeWidth: 16 })
      Column({ space: 3 }) {
