        Text(this.fmt(this.elev)).fontSize(46).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        Text('meters').fontSize(13).fontColor('#9CA3AF')
        Text((this.dir > 0 ? '↑ ascending' : '↓ descending')).fontSize(13).fontWeight(FontWeight.Bold)
          .fontColor(this.dir > 0 ? '#22C55E' : '#38BDF8')
      }
    }
    .width('100%').height('100%').backgroundColor('#000000')
  }
}

@Component
export struct WatchNotificationFb {
  @State private y: number = 120
  @State private op: number = 0
  private frames: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.frames = this.frames + 1
      const p: number = this.frames % 150
      if (p < 35) { this.y = 120 - (p / 35) * 120; this.op = p / 35 }
      else if (p < 115) { this.y = 0; this.op = 1 }
      else { this.y = (p - 115) / 35 * 120; this.op = 1 - (p - 115) / 35 }
    }, 40)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Column({ space: 6 }) {
        Row() {
          Text('💬').fontSize(18)
          Text('Messages').fontSize(12).fontWeight(FontWeight.Bold).fontColor('#60A5FA').margin({ left: 6 }).layoutWeight(1)
          Text('now').fontSize(11).fontColor('#6B7280')
        }.width('100%')
        Text('Alex Rivera').fontSize(15).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        Text('See you at 6! 🎉').fontSize(14).fontColor('#D1D5DB').maxLines(2)
      }
      .width(210).padding(16).backgroundColor('#1B2433').borderRadius(22)
      .alignItems(HorizontalAlign.Start)
      .translate({ y: this.y }).opacity(this.op)
      .shadow({ radius: 16, color: '#55000000', offsetY: 6 })
    }
    .width('100%').height('100%').backgroundColor('#000000')
  }
}

