          Column() {
            Circle().width(64).height(64).fill('#6634D399')
          }.width(64).height(132).justifyContent(FlexAlign.Start).rotate({ angle: i * 60 })
        }, (i: number) => 'p' + i)
      }.width(150).height(150).scale({ x: this.sc, y: this.sc }).rotate({ angle: this.ang })

      Text(this.phase === 0 ? 'Inhale' : 'Exhale').fontSize(22).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
    }
    .width('100%').height('100%').backgroundColor('#04120F')
  }
}

@Component
