  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => { this.prog += 0.006; if (this.prog >= 1) { this.prog = 0 } }, 120)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private tstr(f: number): string {
    const total: number = Math.round(f * 214)
