@Component
export struct WatchMoonFb {
  @State private off: number = -80
  private dir: number = 1
  private t: number = -1
  private bg: string = '#0A1428'

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.off += this.dir * 2
      if (this.off >= 118) { this.off = 118; this.dir = -1 }
      else if (this.off <= -118) { this.off = -118; this.dir = 1 }
    }, 55)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private phaseName(): string {
    if (this.off <= -108) { return 'Full Moon' }
    if (this.off >= 108) { return 'Full Moon' }
    if (Math.abs(this.off) < 12) { return 'New Moon' }
    if (this.dir > 0) { return this.off < 0 ? 'Waning Gibbous' : 'Waning Crescent' }
    return this.off < 0 ? 'Waxing Crescent' : 'Waxing Gibbous'
  }

  build() {
    Column({ space: 12 }) {
      Stack() {
        Circle().width(120).height(120).fill('#E8EAF0')
        Circle().width(120).height(120).fill(this.bg).offset({ x: this.off, y: 0 })
      }.width(120).height(120)
      Text(this.phaseName()).fontSize(19).fontWeight(FontWeight.Bold).fontColor('#E8EAF0')
      Text(Math.round(Math.abs(this.off) / 118 * 100) + '% illuminated').fontSize(13).fontColor('#94A3B8')
    }
    .width('100%').height('100%').justifyContent(FlexAlign.Center).backgroundColor('#0A1428')
  }
}

