      if (this.w <= 0 || this.b <= 0) { this.w = 300; this.b = 300; this.active = 0 }
      else if (this.frames % 14 === 0) { this.active = 1 - this.active }
    }, 200)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private fmt(s: number): string {
    const m: number = Math.floor(s / 60)
    const sec: number = s % 60
    return m + ':' + (sec < 10 ? '0' + sec : '' + sec)
  }

  build() {
    Row({ space: 12 }) {
      Column({ space: 8 }) {
        Text('♔ White').fontSize(13).fontWeight(FontWeight.Bold).fontColor(this.active === 0 ? '#111827' : '#94A3B8')
