      }.layoutWeight(1).height(150).justifyContent(FlexAlign.Center)
      .backgroundColor(this.active === 0 ? '#FFFFFF' : '#E2E8F0').borderRadius(16)
      .border({ width: 2.5, color: this.active === 0 ? '#22C55E' : '#00000000' })
      Column({ space: 8 }) {
        Text('♚ Black').fontSize(13).fontWeight(FontWeight.Bold).fontColor(this.active === 1 ? '#FFFFFF' : '#64748B')
        Text(this.fmt(this.b)).fontSize(38).fontWeight(FontWeight.Bold).fontColor(this.active === 1 ? '#FFFFFF' : '#64748B')
      }.layoutWeight(1).height(150).justifyContent(FlexAlign.Center)
      .backgroundColor(this.active === 1 ? '#1E293B' : '#334155').borderRadius(16)
      .border({ width: 2.5, color: this.active === 1 ? '#22C55E' : '#00000000' })
    }
    .width(300).padding(16).borderRadius(20).backgroundColor('#0F172A')
    .shadow({ radius: 22, color: '#33000000', offsetY: 10 })
  }
}

@Component
export struct CandlestickFb {
  @State private data: number[][] = []
  private t: number = -1

  aboutToAppear(): void {
    let prev: number = 50
    for (let i = 0; i < 16; i++) { const c: number[] = this.gen(prev); this.data.push(c); prev = c[1] }
    this.t = setInterval(() => {
      const prevClose: number = this.data[this.data.length - 1][1]
      const nd: number[][] = this.data.slice(1)
      nd.push(this.gen(prevClose))
      this.data = nd
    }, 380)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private gen(open: number): number[] {
    let close: number = open + (Math.random() * 16 - 8)
    if (close < 22) { close = 22 }
    if (close > 78) { close = 78 }
    const hi: number = Math.max(open, close) + Math.random() * 6
    const lo: number = Math.min(open, close) - Math.random() * 6
    return [open, close, hi, lo]
  }
  private mapY(p: number): number { return 130 - (p - 14) / 72 * 130 }

  build() {
    Column({ space: 14 }) {
      Row() {
        Column({ space: 2 }) {
          Text('BTC / USD').fontSize(13).fontColor('#9AA0A6')
          Text('$' + (this.data[this.data.length - 1][1] * 840).toFixed(0)).fontSize(24).fontWeight(FontWeight.Bold).fontColor('#111827')
        }.alignItems(HorizontalAlign.Start)
        Blank()
        Text(this.data[this.data.length - 1][1] >= this.data[this.data.length - 1][0] ? '▲ bull' : '▼ bear')
          .fontSize(13).fontWeight(FontWeight.Bold)
          .fontColor(this.data[this.data.length - 1][1] >= this.data[this.data.length - 1][0] ? '#16A34A' : '#DC2626')
      }.width('100%')
      Row({ space: 3 }) {
        ForEach(this.data, (c: number[], i: number) => {
          Stack({ alignContent: Alignment.Top }) {
            Column().width(2).height(this.mapY(c[3]) - this.mapY(c[2]))
              .backgroundColor(c[1] >= c[0] ? '#16A34A' : '#DC2626').margin({ top: this.mapY(c[2]) })
            Column().width(11).height(Math.max(2, Math.abs(this.mapY(c[1]) - this.mapY(c[0])))).borderRadius(2)
              .backgroundColor(c[1] >= c[0] ? '#22C55E' : '#EF4444')
              .margin({ top: Math.min(this.mapY(c[0]), this.mapY(c[1])) })
          }.width(13).height(130)
        }, (c: number[], i: number) => i + '_' + Math.round(c[0]) + '_' + Math.round(c[1]))
      }.height(130).alignItems(VerticalAlign.Top)
    }
    .width(300).padding(20).borderRadius(20).backgroundColor('#FFFFFF')
    .shadow({ radius: 22, color: '#14000000', offsetY: 8 })
  }
}

