@Component
export struct TicTacToeFb {
  @State private cells: number[] = [0, 0, 0, 0, 0, 0, 0, 0, 0]
  @State private mi: number = 0
  private moves: number[][] = [[4, 1], [0, 2], [2, 1], [1, 2], [6, 1]]
  private winCells: number[] = [2, 4, 6]
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      if (this.mi < this.moves.length) {
        const nc: number[] = this.cells.slice()
        nc[this.moves[this.mi][0]] = this.moves[this.mi][1]
        this.cells = nc
        this.mi = this.mi + 1
      } else if (this.mi < this.moves.length + 3) {
        this.mi = this.mi + 1
      } else {
        this.cells = [0, 0, 0, 0, 0, 0, 0, 0, 0]
        this.mi = 0
      }
    }, 650)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private won(): boolean { return this.mi >= this.moves.length }
  private isWin(i: number): boolean {
    if (!this.won()) { return false }
    for (let k = 0; k < this.winCells.length; k++) { if (this.winCells[k] === i) { return true } }
    return false
  }
  private mark(v: number): string { return v === 1 ? '✕' : (v === 2 ? '◯' : '') }

  build() {
    Column({ space: 16 }) {
      Text(this.won() ? '✕ wins!' : 'Playing…').fontSize(17).fontWeight(FontWeight.Bold)
        .fontColor(this.won() ? '#22C55E' : '#111827')
      Column({ space: 8 }) {
        ForEach([0, 1, 2], (r: number) => {
          Row({ space: 8 }) {
            ForEach([0, 1, 2], (c: number) => {
              Text(this.mark(this.cells[r * 3 + c])).fontSize(40).fontWeight(FontWeight.Bold)
                .fontColor(this.cells[r * 3 + c] === 1 ? '#6366F1' : '#EF4444')
                .width(72).height(72).textAlign(TextAlign.Center)
                .backgroundColor(this.isWin(r * 3 + c) ? '#DCFCE7' : '#F1F5F9').borderRadius(14)
            }, (c: number) => (r * 3 + c) + '-' + this.cells[r * 3 + c] + (this.isWin(r * 3 + c) ? 'w' : ''))
          }
        }, (r: number) => r.toString())
      }
    }
    .width(300).padding(22).borderRadius(20).backgroundColor('#FFFFFF').alignItems(HorizontalAlign.Center)
    .shadow({ radius: 22, color: '#14000000', offsetY: 8 })
  }
}

