export struct CurrencyExchangeFb {
  @State private rate: number = 0.92
  private dir: number = 0.0007
  private amount: number = 1000
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.rate += this.dir
      if (this.rate >= 0.936) { this.rate = 0.936; this.dir = -0.0007 }
      else if (this.rate <= 0.904) { this.rate = 0.904; this.dir = 0.0007 }
    }, 110)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private money(n: number): string {
    const fixed: string = n.toFixed(2)
    const parts: string[] = fixed.split('.')
    const intp: string = parts[0]
    let out: string = ''
    let cnt: number = 0
    for (let i = intp.length - 1; i >= 0; i--) {
      out = intp.charAt(i) + out
      cnt = cnt + 1
      if (cnt % 3 === 0 && i > 0) { out = ',' + out }
    }
    return out + '.' + parts[1]
  }

  build() {
    Column({ space: 10 }) {
      Row({ space: 12 }) {
        Text('🇺🇸').fontSize(28)
        Column({ space: 2 }) {
          Text('USD').fontSize(15).fontWeight(FontWeight.Bold).fontColor('#111827')
          Text('US Dollar').fontSize(11).fontColor('#9AA0A6')
        }.alignItems(HorizontalAlign.Start).layoutWeight(1)
        Text('$' + this.money(this.amount)).fontSize(19).fontWeight(FontWeight.Bold).fontColor('#111827')
      }.width('100%').padding(14).backgroundColor('#F8FAFC').borderRadius(14)
      Text('⇅').fontSize(18).fontColor('#6366F1')
        .width(38).height(38).textAlign(TextAlign.Center).backgroundColor('#EEF2FF').borderRadius(19)
      Row({ space: 12 }) {
