  aboutToAppear(): void {
    for (let i = 0; i < 32; i++) { if (!this.isBooked(i)) { this.order.push(i) } }
    this.t = setInterval(() => { this.sel = (this.sel + 1) % 7 }, 430)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private isBooked(idx: number): boolean {
    for (let i = 0; i < this.booked.length; i++) { if (this.booked[i] === idx) { return true } }
    return false
  }
  private stateOf(idx: number): number {
    if (this.isBooked(idx)) { return 1 }
    for (let i = 0; i < this.sel; i++) { if (this.order[i] === idx) { return 2 } }
    return 0
  }
  private seatColor(idx: number): string {
    const s: number = this.stateOf(idx)
    if (s === 1) { return '#334155' }
    if (s === 2) { return '#8B5CF6' }
    return '#D5DBE5'
  }

