  aboutToAppear(): void {
    this.t = setInterval(() => {
      const last: number = this.data[this.data.length - 1]
      let nv: number = last + (Math.random() * 26 - 13)
      if (nv < 14) { nv = 14 }
      if (nv > 96) { nv = 96 }
      const nd: number[] = this.data.slice(1)
      nd.push(Math.round(nv))
      this.data = nd
    }, 240)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private pts(): number[][] {
    const w: number = 262
    const h: number = 120
    const n: number = this.data.length
    const res: number[][] = []
    for (let i = 0; i < n; i++) {
      res.push([(i / (n - 1)) * w, h - (this.data[i] / 100) * h])
    }
    return res
  }
  private delta(): number { return this.data[this.data.length - 1] - this.data[this.data.length - 2] }

  build() {
    Column({ space: 16 }) {
      Row() {
        Column({ space: 2 }) {
          Text('Revenue').fontSize(13).fontColor('#9AA0A6')
          Text('$' + this.data[this.data.length - 1] + 'k').fontSize(28).fontWeight(FontWeight.Bold).fontColor('#111111')
