export struct DiceRollFb {
  @State private d1: number = 3
  @State private d2: number = 5
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      this.d1 = 1 + Math.floor(Math.random() * 6)
      this.d2 = 1 + Math.floor(Math.random() * 6)
    }, 140)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  private isOn(v: number, idx: number): boolean {
    if (v === 1) { return idx === 4 }
    if (v === 2) { return idx === 0 || idx === 8 }
    if (v === 3) { return idx === 0 || idx === 4 || idx === 8 }
    if (v === 4) { return idx === 0 || idx === 2 || idx === 6 || idx === 8 }
    if (v === 5) { return idx === 0 || idx === 2 || idx === 4 || idx === 6 || idx === 8 }
    return idx === 0 || idx === 2 || idx === 3 || idx === 5 || idx === 6 || idx === 8
  }

  @Builder
  Die(which: number) {
    Column({ space: 9 }) {
      ForEach([0, 1, 2], (r: number) => {
        Row({ space: 9 }) {
          ForEach([0, 1, 2], (c: number) => {
            Circle().width(13).height(13)
              .fill(this.isOn(which === 1 ? this.d1 : this.d2, r * 3 + c) ? '#111827' : '#00000000')
          }, (c: number) => (r * 3 + c) + (this.isOn(which === 1 ? this.d1 : this.d2, r * 3 + c) ? 'x' : 'o'))
        }
      }, (r: number) => r.toString())
    }
    .width(88).height(88).padding(13).backgroundColor('#FFFFFF').borderRadius(16)
    .shadow({ radius: 10, color: '#1A000000', offsetY: 3 })
  }

  build() {
    Column({ space: 18 }) {
      Text('🎲 Roll the Dice').fontSize(16).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
      Row({ space: 20 }) {
        this.Die(1)
        this.Die(2)
      }
      Text('Total ' + (this.d1 + this.d2)).fontSize(20).fontWeight(FontWeight.Bold).fontColor('#FBBF24')
    }
    .width(300).padding(26).borderRadius(24).backgroundColor('#166534')
    .shadow({ radius: 24, color: '#33000000', offsetY: 10 })
  }
}

