@Component
export struct ThermostatFb {
  @State private temp: number = 21
  private targets: number[] = [19, 22, 24, 21, 20]
  private i: number = 0
  private t: number = -1

  aboutToAppear(): void {
    this.t = setInterval(() => {
      const target: number = this.targets[this.i]
      if (Math.abs(this.temp - target) < 0.06) {
        this.i = (this.i + 1) % this.targets.length
      } else {
        this.temp += (target - this.temp) * 0.14
      }
    }, 55)
  }
  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  build() {
    Column({ space: 14 }) {
      Row() {
        Text('🏠 Living Room').fontSize(14).fontColor('#C7CBD1')
        Blank()
