@Component
export struct CounterFb {
  @Link value: number

  private fmt(n: number): string {
    const s: string = Math.round(n).toString()
    let out: string = ''
    let cnt: number = 0
    for (let i: number = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out
      cnt++
      if (cnt % 3 === 0 && i > 0) { out = ',' + out }
    }
    return out
  }

  build() {
    Column({ space: 6 }) {
      Text('👀').fontSize(30)
      Text(this.fmt(this.value)).fontSize(48).fontWeight(FontWeight.Bold).fontColor('#6D28D9')
