  private play(): void {
    this.s = 0; this.ringScale = 0.5; this.ringOpacity = 0.5
    animateTo({ duration: 450, curve: Curve.Friction }, () => { this.s = 1 })
    animateTo({ duration: 700, curve: Curve.EaseOut, onFinish: () => { setTimeout(() => { this.play() }, 800) } }, () => {
