  @Builder
  Box(value: string, label: string) {
    Column({ space: 6 }) {
      Text(value).fontSize(28).fontWeight(FontWeight.Bold).fontColor('#FFFFFF')
        .width(64).height(64).textAlign(TextAlign.Center)
        .backgroundColor('#312E81').borderRadius(14)
      Text(label).fontSize(11).fontColor('#9AA0A6')
    }
  }

  build() {
    Row({ space: 10 }) {
      this.Box(this.pad(Math.floor(this.remaining / 86400)), 'DAYS')
      this.Box(this.pad(Math.floor((this.remaining % 86400) / 3600)), 'HOURS')
      this.Box(this.pad(Math.floor((this.remaining % 3600) / 60)), 'MIN')
      this.Box(this.pad(Math.floor(this.remaining % 60)), 'SEC')
    }
  }
}

