  aboutToDisappear(): void { if (this.t >= 0) { clearInterval(this.t); this.t = -1 } }

  @Builder
  Bubble(text: string, mine: boolean) {
    Row() {
      if (mine) { Blank() }
      Text(text).fontSize(14)
        .fontColor(mine ? '#FFFFFF' : '#1F2937')
        .backgroundColor(mine ? '#8B5CF6' : '#FFFFFF')
        .padding({ left: 15, right: 15, top: 11, bottom: 11 })
        .borderRadius(16).constraintSize({ maxWidth: 220 })
        .shadow({ radius: 6, color: '#0D000000', offsetY: 2 })
      if (!mine) { Blank() }
