  @State private angle: number = 0
  private timerId: number = -1
  private cards: SwipeCardData[] = [
    { title: 'Explore', sub: '+30 places', c1: '#4338CA', c2: '#6D28D9' },
    { title: 'Discover', sub: '+18 spots', c1: '#F97316', c2: '#DB2777' },
