// GradientStepsSliderFb3.ets
// Fb3 - Gradient Slider with Steps (ArkUI / ArkTS)
//
// Usage:
//  @State v: number = 50
//  GradientStepsSliderFb3({ value: $v, config: { min: 0, max: 100, divisions: 10 } })

export interface Fb3Style {
  height: number                // container height
  radius: number                // container radius
  paddingX: number              // left/right inner padding
  trackHeight: number           // slider track thickness
  thumbRadius: number           // thumb radius (white circle)
  tickRadius: number            // dot radius
  accentColor: ResourceColor    // track + inactive dots
  activeDotColor: ResourceColor // active dots color
  gradientStops: Array<[ResourceColor, number]> // background gradient stops
}

export interface Fb3Config {
  min: number
  max: number
  divisions: number
  showMinMaxText: boolean
  style?: Partial<Fb3Style>
}

const DEFAULT_STYLE: Fb3Style = {
  height: 52,
  radius: 15,
  paddingX: 16,
  trackHeight: 4,
  thumbRadius: 20,
  tickRadius: 2,
  accentColor: Color.White,
  activeDotColor: Color.Orange,
  gradientStops: [
    [Color.Orange, 0.0],
    [Color.Green, 1.0],
  ]
}

const DEFAULT_CONFIG: Fb3Config = {
  min: 0,
  max: 100,
  divisions: 10,
  showMinMaxText: true,
  style: {}
}

function clamp01(v: number): number {
  if (v < 0) return 0
  if (v > 1) return 1
  return v
}

function clamp(v: number, min: number, max: number): number {
  if (v < min) return min
  if (v > max) return max
  return v
}

// ArkUI size callbacks sometimes give Length (number | string).
// We keep it safe and explicit.
function lenToNumber(v: Length): number {
  if (typeof v === 'number') return v
  if (typeof v === 'string') {
    const n = Number.parseFloat(v)
    return Number.isFinite(n) ? n : 0
  }
  // If it's a Resource (rare for runtime size), fall back.
  return 0
}

@Component
export struct GradientStepsSliderFb3 {
  // two-way binding (no function prop needed)
  @Link value: number

  @Prop config?: Fb3Config

  @State private trackW: number = 0

  private cfg(): Fb3Config {
    return this.config ?? DEFAULT_CONFIG
  }

  private st(): Fb3Style {
    const c: Fb3Config = this.cfg()
    const s: Partial<Fb3Style> = c.style ?? {}
    // merge without spread (arkts-no-spread)
    return {
      height: s.height ?? DEFAULT_STYLE.height,
      radius: s.radius ?? DEFAULT_STYLE.radius,
      paddingX: s.paddingX ?? DEFAULT_STYLE.paddingX,
      trackHeight: s.trackHeight ?? DEFAULT_STYLE.trackHeight,
      thumbRadius: s.thumbRadius ?? DEFAULT_STYLE.thumbRadius,
      tickRadius: s.tickRadius ?? DEFAULT_STYLE.tickRadius,
      accentColor: s.accentColor ?? DEFAULT_STYLE.accentColor,
      activeDotColor: s.activeDotColor ?? DEFAULT_STYLE.activeDotColor,
      gradientStops: s.gradientStops ?? DEFAULT_STYLE.gradientStops
    }
  }

  private min(): number { return this.cfg().min }
  private max(): number { return this.cfg().max }
  private divisions(): number { return this.cfg().divisions }
  private showMinMax(): boolean { return this.cfg().showMinMaxText }

  private range(): number {
    const r: number = this.max() - this.min()
    return r <= 0 ? 1 : r
  }

  private ratio(): number {
    const r: number = (this.value - this.min()) / this.range()
    return clamp01(r)
  }

  private activeIndex(): number {
    const div: number = this.divisions()
    if (div <= 0) return 0
    return Math.round(this.ratio() * div)
  }

  // We keep thumb center inside track so it never clips at ends
  private minCenterX(): number {
    return this.st().paddingX + this.st().thumbRadius
  }

  private maxCenterX(): number {
    return this.st().paddingX + (this.trackW > 0 ? this.trackW : 0) - this.st().thumbRadius
  }

  private thumbCenterX(): number {
    const minX: number = this.minCenterX()
    const maxX: number = this.maxCenterX()
    const w: number = maxX - minX
    return minX + this.ratio() * (w > 0 ? w : 0)
  }

  private snapValueFromCenterX(centerX: number): number {
    const minX: number = this.minCenterX()
    const maxX: number = this.maxCenterX()
    const w: number = maxX - minX
    const r: number = w <= 0 ? 0 : clamp01((centerX - minX) / w)

    const raw: number = this.min() + r * this.range()

    const div: number = this.divisions()
    if (div <= 0) {
      return clamp(raw, this.min(), this.max())
    }

    const step: number = this.range() / div
    const snappedSteps: number = Math.round((raw - this.min()) / step)
    const snapped: number = this.min() + snappedSteps * step
    return clamp(snapped, this.min(), this.max())
  }

  // ============== UI parts ==============

  @Builder
  private TrackAndThumb() {
    // Track container (used only to measure width)
    Stack() {
      // inactive track line (accent with low opacity)
      Row() {}
      .width('100%')
      .height(this.st().trackHeight)
      .borderRadius(this.st().trackHeight / 2)
      .backgroundColor(this.st().accentColor)
      .opacity(0.25)
      .position({
        x: 0,
        y: (this.st().height - this.st().trackHeight) / 2
      })

      // active track line (accent full)
      Row() {}
      .width(this.thumbCenterX() - this.minCenterX())
      .height(this.st().trackHeight)
      .borderRadius(this.st().trackHeight / 2)
      .backgroundColor(this.st().accentColor)
      .position({
        x: this.minCenterX() - this.st().thumbRadius,
        y: (this.st().height - this.st().trackHeight) / 2
      })

      // dots (steps)
      if (this.divisions() > 0) {
        Row() {
          ForEach(
            new Array<number>(this.divisions() + 1).fill(0).map((_, i) => i),
            (i: number) => {
              Row() {}
              .width(this.st().tickRadius * 2)
              .height(this.st().tickRadius * 2)
              .borderRadius(this.st().tickRadius)
              .backgroundColor(i <= this.activeIndex() ? this.st().activeDotColor : this.st().accentColor)
              .opacity(i <= this.activeIndex() ? 1.0 : 0.9)
            },
            (i: number) => i.toString()
          )
        }
        .width(this.maxCenterX() - this.minCenterX())
        .justifyContent(FlexAlign.SpaceBetween)
        .position({
          x: this.minCenterX(),
          y: (this.st().height - this.st().trackHeight) / 2 +
            (this.st().trackHeight / 2) -
          this.st().tickRadius
        })
      }

      // thumb (white circle + value text)
      Stack() {
        Row() {}
        .width(this.st().thumbRadius * 2)
        .height(this.st().thumbRadius * 2)
        .borderRadius(this.st().thumbRadius)
        .backgroundColor(Color.White)

        Text(this.value.toFixed(0))
          .fontSize(this.st().thumbRadius * 0.9)
          .fontWeight(FontWeight.Bold)
          .fontColor(this.st().gradientStops[0][0]) // text color = gradient start
      }
      .width(this.st().thumbRadius * 2)
      .height(this.st().thumbRadius * 2)
      .position({
        x: this.thumbCenterX() - this.st().thumbRadius,
        y: (this.st().height - this.st().thumbRadius * 2) / 2
      })
    }
    .width('100%')
    .height(this.st().height)
    .onAreaChange((_: Area, n: Area) => {
      // n.width might be Length
      this.trackW = lenToNumber(n.width)
    })
    .gesture(
      PanGesture()
        .onActionUpdate((e: GestureEvent) => {
          // localX is inside this TrackAndThumb area
          const localX: number = e.fingerList[0].localX
          const v: number = this.snapValueFromCenterX(localX)
          this.value = v
        })
        .onActionEnd((e: GestureEvent) => {
          const v: number = this.snapValueFromCenterX(e.fingerList[0].localX)
          this.value = v
        })
    )
  }

  build() {
    Row() {

      if (this.cfg().showMinMaxText) {
        Text(String(this.cfg().min.toFixed(0)))
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .fontColor(Color.White)
          .width(36)
          .textAlign(TextAlign.Center)
      }

      // ✅ Builder'ı container içine koy
      Stack() {
        this.TrackAndThumb()
      }
      .layoutWeight(1)

      if (this.cfg().showMinMaxText) {
        Text(String(this.cfg().max.toFixed(0)))
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .fontColor(Color.White)
          .width(36)
          .textAlign(TextAlign.Center)
      }
    }
    .width('100%')
    .height(this.st().height)
    .padding({ left: this.st().paddingX, right: this.st().paddingX })
    .borderRadius(this.st().radius)
    .linearGradient({
      angle: 0,
      colors: this.st().gradientStops
    })
  }

}

// GradientSliderFb2.ets

export interface Fb2Gradient {
  startColor: string
  endColor: string
}

export interface Fb2Style {
  height?: number
  radius?: number
  paddingX?: number

  trackHeight?: number
  accentColor?: string
  inactiveAlpha?: number

  thumbRadius?: number
  thumbBgColor?: string
  thumbTextColor?: string

  minMaxFontSize?: number
  minMaxFontWeight?: number
  minMaxTextColor?: string
}

export interface Fb2Config {
  min?: number
  max?: number
  showMinMaxText?: boolean
  divisions?: number

  gradient?: Fb2Gradient
  style?: Fb2Style
}

function clamp01(v: number): number {
  if (v < 0) return 0
  if (v > 1) return 1
  return v
}

function clamp(v: number, minV: number, maxV: number): number {
  if (v < minV) return minV
  if (v > maxV) return maxV
  return v
}

function toNumberLen(v: number | string): number {
  if (typeof v === 'number') return v
  const n: number = Number(v)
  return isNaN(n) ? 0 : n
}

function withAlpha(color: string, alpha01: number): string {
  const a: number = Math.round(clamp01(alpha01) * 255)
  const aHex: string = a.toString(16).padStart(2, '0')
  if (color.startsWith('#') && color.length === 7) {
    return `#${aHex}${color.substring(1)}`
  }
  if (color.startsWith('#') && color.length === 9) {
    return `#${aHex}${color.substring(3)}`
  }
  return color
}

@Component
export struct GradientSliderFb2 {
  @Link value: number
  @Prop config?: Fb2Config

  @State private trackW: number = 0

  // config getters
  private min(): number { return this.config?.min ?? 0 }
  private max(): number { return this.config?.max ?? 100 }
  private showMinMax(): boolean { return this.config?.showMinMaxText ?? true }
  private divisions(): number { return this.config?.divisions ?? 0 }

  private hheight(): number { return this.config?.style?.height ?? 52 }
  private radius(): number { return this.config?.style?.radius ?? 15 }
  private paddingX(): number { return this.config?.style?.paddingX ?? 15.5 }

  private trackHeight(): number { return this.config?.style?.trackHeight ?? 4 }
  private accent(): string { return this.config?.style?.accentColor ?? '#FFFFFF' }
  private inactiveAlpha(): number { return this.config?.style?.inactiveAlpha ?? 0.18 }

  private thumbRadius(): number { return this.config?.style?.thumbRadius ?? 20 }
  private thumbBg(): string { return this.config?.style?.thumbBgColor ?? '#FFFFFF' }

  private gradStart(): string { return this.config?.gradient?.startColor ?? '#3F51B5' }
  private gradEnd(): string { return this.config?.gradient?.endColor ?? '#673AB7' }

  private minMaxFontSize(): number { return this.config?.style?.minMaxFontSize ?? 16 }
  private minMaxFontWeight(): number { return this.config?.style?.minMaxFontWeight ?? 700 }
  private minMaxTextColor(): string { return this.config?.style?.minMaxTextColor ?? '#FFFFFF' }

  private thumbTextColor(): string {
    return this.config?.style?.thumbTextColor ?? this.gradStart()
  }

  private ratio(): number {
    const minV: number = this.min()
    const maxV: number = this.max()
    if (maxV <= minV) return 0
    return clamp01((this.value - minV) / (maxV - minV))
  }

  private valueFromRatio(r: number): number {
    return this.min() + (this.max() - this.min()) * clamp01(r)
  }

  private snap(v: number): number {
    const div: number = this.divisions()
    if (div <= 0) return v
    const step: number = (this.max() - this.min()) / div
    if (step <= 0) return v
    const idx: number = Math.round((v - this.min()) / step)
    return this.min() + idx * step
  }

  private updateByLocalX(localX: number): void {
    const w: number = this.trackW
    if (w <= 1) return
    const r: number = clamp01(localX / w)
    let v: number = this.valueFromRatio(r)
    v = this.snap(v)
    this.value = clamp(v, this.min(), this.max())
  }

  private activeW(): number {
    return this.ratio() * this.trackW
  }

  private thumbX(): number {
    const half: number = this.thumbRadius()
    const cx: number = this.ratio() * this.trackW
    const clampedCx: number = Math.min(Math.max(cx, half), this.trackW - half)
    return clampedCx - half
  }

  private formatInt(v: number): string {
    return Math.round(v).toString()
  }

  build() {
    Row() {
      // MIN
      if (this.showMinMax()) {
        Text(this.formatInt(this.min()))
          .fontSize(this.minMaxFontSize())
          .fontWeight(this.minMaxFontWeight())
          .fontColor(this.minMaxTextColor())
          .textAlign(TextAlign.Center)
          .margin({ right: 8 })
      }

      // TRACK
      Stack() {
        // inactive
        Row() { }
        .width('100%')
        .height(this.trackHeight())
        .backgroundColor(withAlpha(this.accent(), this.inactiveAlpha()))
        .borderRadius(this.trackHeight() / 2)
        .position({ x: 0, y: (this.hheight() - this.trackHeight()) / 2 })

        // active
        Row() { }
        .width(this.activeW())
        .height(this.trackHeight())
        .backgroundColor(this.accent())
        .borderRadius(this.trackHeight() / 2)
        .position({ x: 0, y: (this.hheight() - this.trackHeight()) / 2 })

        // thumb
        Stack() {
          Row() { }
          .width(this.thumbRadius() * 2)
          .height(this.thumbRadius() * 2)
          .backgroundColor(this.thumbBg())
          .borderRadius(this.thumbRadius())

          Text(this.formatInt(this.value))
            .fontSize(this.thumbRadius() * 0.8)
            .fontWeight(700)
            .fontColor(this.thumbTextColor())
            .textAlign(TextAlign.Center)
        }
        .width(this.thumbRadius() * 2)
        .height(this.thumbRadius() * 2)
        .position({
          x: this.thumbX(),
          y: (this.hheight() - this.thumbRadius() * 2) / 2
        })

        // gestures
        Row() { }
        .width('100%')
        .height(this.hheight())
        .opacity(0.001)
        .gesture(
          GestureGroup(GestureMode.Exclusive,
            PanGesture({ direction: PanDirection.Horizontal })
              .onActionStart((e: GestureEvent) => {
                this.updateByLocalX(e.fingerList[0].localX)
              })
              .onActionUpdate((e: GestureEvent) => {
                this.updateByLocalX(e.fingerList[0].localX)
              }),
            TapGesture()
              .onAction((e: GestureEvent) => {
                this.updateByLocalX(e.fingerList[0].localX)
              })
          )
        )
      }
      .layoutWeight(1)
      .height(this.hheight())
      .onAreaChange((o: Area, n: Area) => {
        this.trackW = Number(n.width)
      })

      // MAX
      if (this.showMinMax()) {
        Text(this.formatInt(this.max()))
          .fontSize(this.minMaxFontSize())
          .fontWeight(this.minMaxFontWeight())
          .fontColor(this.minMaxTextColor())
          .textAlign(TextAlign.Center)
          .margin({ left: 8 })
      }
    }
    .width('100%')
    .height(this.hheight())
    .padding({ left: this.paddingX(), right: this.paddingX() })
    .borderRadius(this.radius())
    // ✅ FIX: use angle instead of GradientDirection.LeftToRight
    .linearGradient({
      angle: 0, // 0° = left -> right
      colors: [
        [this.gradStart(), 0.0],
        [this.gradEnd(), 1.0]
      ]
    })
  }
}

// components/curved_nav_flutter_like.ets

export interface CurvedNavItem {
  key: string
  icon: Resource
  index: number
}

export interface CurvedNavStyle {
  // Visible height (Flutter widget.height)
  height?: number                  // default 75

  // Painter area height (Flutter fixed 75)
  painterHeight?: number           // default 75

  // Colors
  barColor?: string                // Flutter widget.color
  backgroundColor?: string         // Flutter widget.backgroundColor
  buttonBgColor?: string           // Flutter widget.buttonBackgroundColor ?? color

  // Painter params (Flutter)
  s?: number                       // default 0.2
  sideGap?: number                 // default 0.1

  // Nav button effects (Flutter)
  navItemLift?: number             // default 40

  // Center button motion
  centerLift?: number              // default 80
  centerSize?: number              // default 56

  // Flutter: bottom: -40 - (75 - height)
  centerBottomOffset?: number      // if not set -> formula

  // Animation
  animDurationMs?: number          // default 600

  navBaseOffsetY?: number // default 16
}

export interface CurvedNavConfig {
  items?: CurvedNavItem[]
  style?: CurvedNavStyle
}

@Component
export struct CurvedNavigationBarFb {
  @Link selectedIndex: number
  @Prop config?: CurvedNavConfig

  // Animated position in [0..1]
  @State private pos: number = 0
  @State private internalIndex: number = 0

  // Layout widths
  @State private rowWidth: Length = 0
  @State private canvasW: Length = 0
  @State private canvasH: Length = 0

  private ctx: CanvasRenderingContext2D = new CanvasRenderingContext2D()

  private navBaseOffsetY(): number { return this.st().navBaseOffsetY ?? 28 }

  aboutToAppear() {
    this.internalIndex = this.safeIndex(this.selectedIndex)
    this.pos = this.internalIndex / this.lengthSafe()
  }

  build() {
    Stack({ alignContent: Alignment.Bottom }) {

      // Background behind everything (Flutter container backgroundColor)
      Column() { }
      .width('100%')
      .height(this.hheight())
      .backgroundColor(this.bbackgroundColor())

      // Curved bar painter (Flutter CustomPaint)
      Canvas(this.ctx)
        .width('100%')
        .height(this.painterHeight())
        .position({ x: 0, y: this.hheight() - this.painterHeight() })
        .onReady(() => {
          this.drawBar()
        })
        .onAreaChange((o: Area, n: Area) => {
          this.canvasW = n.width
          this.canvasH = n.height
          this.drawBar()
        })

      // Buttons Row (Flutter: SizedBox(height:100) Row Expanded NavButton)
      Row() {
        ForEach(this.items(), (it: CurvedNavItem) => {
          this.NavButton(it)
        }, (it: CurvedNavItem) => it.key)
      }
      .width('100%')
      .height(100)
      .alignItems(VerticalAlign.Center) // ✅ ekle
      .position({ x: 0, y: this.hheight() - 100 })
      .onAreaChange((o: Area, n: Area) => {
        // ✅ Single source of truth for width (Flutter maxWidth)
        this.rowWidth = n.width
        // width changes => repaint (safe)
        this.drawBar()
      })

      // Center moving circle area (Flutter Positioned: left=_pos*maxWidth, width=maxWidth/len)
      // We create a "cell" whose width = itemWidth and place circle centered inside it.
      Stack() {
        this.CenterCircle()
      }
      .width(this.itemWidth())
      .height(this.painterHeight())
      .position({
        x: this.leftX(),
        y: this.hheight() - this.painterHeight() + this.centerBottomOffset()
      })
    }
    .width('100%')
    .height(this.hheight())
    .clip(false)
  }

  // ---------------- UI ----------------

  @Builder
  private NavButton(item: CurvedNavItem) {
    Column() {
      Image(item.icon)
        .width(26)
        .height(26)
        .objectFit(ImageFit.Contain)
        .translate({ x: 0, y: this.navBaseOffsetY() - this.navTranslateY(item.index) })
        .opacity(this.navOpacity(item.index))
    }
    .width(this.itemWidth())
    .height(75)
    .onClick(() => {
      this.setIndex(item.index)
    })
  }

  @Builder
  private CenterCircle() {
    // Center inside its "cell" like Flutter: Center(child: Transform.translate(...))
    Stack() {
      Column() { }
      .width(this.centerSize())
      .height(this.centerSize())
      .backgroundColor(this.buttonBgColor())
      .borderRadius(this.centerSize() / 2)

      Image(this.activeIcon())
        .width(26)
        .height(26)
        .objectFit(ImageFit.Contain)
    }
    .width(this.centerSize())
    .height(this.centerSize())
    .align(Alignment.Center)
    // Flutter: Transform.translate y: -(1 - _buttonHide) * 80
    // We approximate "hide" using distance to nearest item center (stable & smooth)
    .translate({ x: 0, y: -(this.centerLiftT() * this.centerLift()) })
  }

  // ---------------- State + animation (no @Watch) ----------------

  private setIndex(index: number) {
    const len: number = this.lengthSafe()
    if (len <= 0) return

    const safe: number = this.safeIndex(index)
    if (safe === this.internalIndex) return

    this.internalIndex = safe
    this.selectedIndex = safe

    const to: number = safe / len
    animateTo({ duration: this.animDurationMs(), curve: Curve.EaseOut }, () => {
      this.pos = to
      // repaint during animation; pos changes update UI anyway but canvas needs redraw
      this.drawBar()
    })
  }

  // ---------------- Flutter painter port ----------------

  private drawBar() {
    const w: number = this.lenToNumber(this.canvasW)
    const h: number = this.lenToNumber(this.canvasH)
    if (w <= 0 || h <= 0) return

    const len: number = this.lengthSafe()
    if (len <= 0) return

    const ctx: CanvasRenderingContext2D = this.ctx
    ctx.clearRect(0, 0, w, h)

    // Flutter:
    // span = 1/len
    // s = 0.2
    // l = startingLoc + (span - s)/2
    // loc = l (LTR)
    const span: number = 1 / len
    const s: number = this.s()
    const gap: number = this.sideGap()
    const loc: number = this.pos + (span - s) / 2

    ctx.save()
    ctx.beginPath()

    ctx.moveTo(0, 0)
    ctx.lineTo((loc - gap) * w, 0)

    // cubic #1
    ctx.bezierCurveTo(
      (loc + s * 0.20) * w, h * 0.05,
      loc * w,              h * 0.60,
      (loc + s * 0.50) * w, h * 0.60
    )

    // cubic #2
    ctx.bezierCurveTo(
      (loc + s) * w,               h * 0.60,
      (loc + s - s * 0.20) * w,    h * 0.05,
      (loc + s + gap) * w,         0
    )

    ctx.lineTo(w, 0)
    ctx.lineTo(w, h)
    ctx.lineTo(0, h)
    ctx.closePath()

    ctx.fillStyle = this.barColor()
    ctx.fill()

    ctx.restore()
  }

  // ---------------- NavButton math (Flutter) ----------------

  private navDesiredPos(index: number): number {
    return (1 / this.lengthSafe()) * index
  }

  private navDiff(index: number): number {
    return Math.abs(this.pos - this.navDesiredPos(index))
  }

  private navTranslateY(index: number): number {
    const len: number = this.lengthSafe()
    const diff: number = this.navDiff(index)
    const verticalAlignment: number = 1 - (len * diff)
    return diff < (1 / len) ? (verticalAlignment * this.navItemLift()) : 0
  }

  private navOpacity(index: number): number {
    const len: number = this.lengthSafe()
    const diff: number = this.navDiff(index)
    const op: number = len * diff
    return diff < (1 / len) * 0.99 ? op : 1
  }

  // ---------------- Center lift factor ----------------

  private centerLiftT(): number {
    const len: number = this.lengthSafe()
    if (len <= 0) return 0
    const nearestIndex: number = Math.round(this.pos * len)
    const nearestPos: number = nearestIndex / len
    const diff: number = Math.abs(this.pos - nearestPos)
    return Math.max(0, 1 - (diff * len))
  }

  // ---------------- Layout: THE FIX (use rowWidth like Flutter maxWidth) ----------------

  private totalWidth(): number {
    // ✅ Single source of truth: Row width (Flutter maxWidth)
    const w: number = this.lenToNumber(this.rowWidth)
    if (w > 0) return w
    // fallback to canvas width
    return this.lenToNumber(this.canvasW)
  }

  private itemWidth(): number {
    const len: number = this.lengthSafe()
    const w: number = this.totalWidth()
    return len <= 0 ? 0 : (w / len)
  }

  private leftX(): number {
    // Flutter: left = _pos * maxWidth
    return this.pos * this.totalWidth()
  }

  // ---------------- Defaults / config ----------------

  private cfg(): CurvedNavConfig { return this.config ?? {} }
  private st(): CurvedNavStyle { return this.cfg().style ?? {} }

  private items(): CurvedNavItem[] {
    const its: CurvedNavItem[] | undefined = this.cfg().items
    if (its && its.length > 0) return its
    return [
      { key: 'home', icon: $r('app.media.startIcon'), index: 0 },
      { key: 'search', icon: $r('app.media.startIcon'), index: 1 },
      { key: 'cart', icon: $r('app.media.startIcon'), index: 2 },
      { key: 'calendar', icon: $r('app.media.startIcon'), index: 3 }
    ]
  }

  private lengthSafe(): number {
    return this.items().length
  }

  private safeIndex(i: number): number {
    const len: number = this.lengthSafe()
    if (len <= 0) return 0
    if (i < 0) return 0
    if (i >= len) return len - 1
    return i
  }

  private hheight(): number { return this.st().height ?? 75 }
  private painterHeight(): number { return this.st().painterHeight ?? 75 }

  private barColor(): string { return this.st().barColor ?? '#000000' }
  private bbackgroundColor(): string { return this.st().backgroundColor ?? '#FFFFFF' }
  private buttonBgColor(): string { return this.st().buttonBgColor ?? this.barColor() }

  private s(): number { return this.st().s ?? 0.2 }
  private sideGap(): number { return this.st().sideGap ?? 0.1 }

  private navItemLift(): number { return this.st().navItemLift ?? 40 }
  private centerLift(): number { return this.st().centerLift ?? 15 }
  private centerSize(): number { return this.st().centerSize ?? 56 }

  private centerBottomOffset(): number {
    const v: number | undefined = this.st().centerBottomOffset
    if (v !== undefined) return v
    // Flutter: -40 - (75 - height)
    return -40 - (75 - this.hheight())
  }

  private animDurationMs(): number { return this.st().animDurationMs ?? 600 }

  private activeIcon(): Resource {
    const idx: number = this.safeIndex(this.internalIndex)
    return this.items()[idx].icon
  }

  private lenToNumber(v: Length): number {
    if (typeof v === 'number') return v
    if (typeof v === 'string') {
      const n: number = parseFloat(v)
      return isNaN(n) ? 0 : n
    }
    return 0
  }
}

export interface SliderFb1Style {
  trackHeight?: number
  thumbRadius?: number
  widthPadding?: number
  barHeight?: number

  primaryColor?: string
  thumbBgColor?: string
  inactiveAlpha?: number

  valueFontSize?: number
  valueFontWeight?: number
}

export interface SliderFb1Config {
  min?: number
  max?: number
  divisions?: number
  style?: SliderFb1Style
}

function clamp01(v: number): number {
  if (v < 0) return 0
  if (v > 1) return 1
  return v
}

function clamp(v: number, minV: number, maxV: number): number {
  if (v < minV) return minV
  if (v > maxV) return maxV
  return v
}

function withAlpha(color: string, alpha01: number): string {
  const a: number = Math.round(clamp01(alpha01) * 255)
  const aHex: string = a.toString(16).padStart(2, '0')
  if (color.startsWith('#') && color.length === 7) {
    return `#${aHex}${color.substring(1)}`
  }
  if (color.startsWith('#') && color.length === 9) {
    return `#${aHex}${color.substring(3)}`
  }
  return color
}

@Component
export struct SliderFb1Simple {
  @Link value: number
  @Prop config?: SliderFb1Config

  @State private trackW: number = 0

  // Config getters
  private min(): number { return this.config?.min ?? 0 }
  private max(): number { return this.config?.max ?? 100 }
  private divisions(): number { return this.config?.divisions ?? 0 }

  private primary(): string { return this.config?.style?.primaryColor ?? '#3F51B5' }
  private inactiveAlpha(): number { return this.config?.style?.inactiveAlpha ?? 0.18 }

  private trackHeight(): number { return this.config?.style?.trackHeight ?? 4 }
  private thumbR(): number { return this.config?.style?.thumbRadius ?? 20 }

  private padX(): number { return this.config?.style?.widthPadding ?? 18 }
  private barH(): number { return this.config?.style?.barHeight ?? 70 }

  private thumbBg(): string { return this.config?.style?.thumbBgColor ?? '#FFFFFF' }

  private valueFontSize(): number { return this.config?.style?.valueFontSize ?? 18 }
  private valueFontWeight(): number { return this.config?.style?.valueFontWeight ?? 700 }

  // Math
  private ratio(): number {
    if (this.max() <= this.min()) return 0
    return clamp01((this.value - this.min()) / (this.max() - this.min()))
  }

  private valueFromRatio(r: number): number {
    return this.min() + (this.max() - this.min()) * clamp01(r)
  }

  private snap(v: number): number {
    const div: number = this.divisions()
    if (div <= 0) return v
    const step: number = (this.max() - this.min()) / div
    const idx: number = Math.round((v - this.min()) / step)
    return this.min() + idx * step
  }

  private usableW(): number {
    const w: number = this.trackW - this.padX() * 2
    return w > 0 ? w : 0
  }

  private thumbCenterX(): number {
    const cx: number = this.padX() + this.ratio() * this.usableW()
    const minCx: number = this.padX() + this.thumbR()
    const maxCx: number = this.padX() + this.usableW() - this.thumbR()
    return clamp(cx, minCx, maxCx)
  }

  private thumbLeftX(): number {
    return this.thumbCenterX() - this.thumbR()
  }

  private updateByLocalX(localX: number): void {
    const w: number = this.usableW()
    if (w <= 1) return

    const x: number = clamp(localX - this.padX(), 0, w)
    const r: number = clamp01(x / w)

    let v: number = this.valueFromRatio(r)
    v = this.snap(v)
    this.value = clamp(v, this.min(), this.max())
  }

  private format(v: number): string {
    return Math.round(v).toString()
  }

  build() {
    Stack() {

      // Inactive track
      Row() { }
      .width(this.usableW())
      .height(this.trackHeight())
      .backgroundColor(withAlpha(this.primary(), this.inactiveAlpha()))
      .borderRadius(this.trackHeight() / 2)
      .position({ x: this.padX(), y: (this.barH() - this.trackHeight()) / 2 })

      // Active track
      Row() { }
      .width(this.ratio() * this.usableW())
      .height(this.trackHeight())
      .backgroundColor(this.primary())
      .borderRadius(this.trackHeight() / 2)
      .position({ x: this.padX(), y: (this.barH() - this.trackHeight()) / 2 })

      // Thumb (value inside)
      Stack() {
        Row() { }
        .width(this.thumbR() * 2)
        .height(this.thumbR() * 2)
        .backgroundColor(this.thumbBg())
        .borderRadius(this.thumbR())

        Text(this.format(this.value))
          .fontSize(this.valueFontSize())
          .fontWeight(this.valueFontWeight())
          .fontColor(this.primary())
          .textAlign(TextAlign.Center)
      }
      .width(this.thumbR() * 2)
      .height(this.thumbR() * 2)
      .position({
        x: this.thumbLeftX(),
        y: (this.barH() - this.trackHeight()) / 2 - (this.thumbR() * 2 - this.trackHeight()) / 2
      })

      // Gesture layer
      Row() { }
      .width('100%')
      .height('100%')
      .opacity(0.001)
      .gesture(
        GestureGroup(GestureMode.Exclusive,
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart((e: GestureEvent) => {
              this.updateByLocalX(e.fingerList[0].localX)
            })
            .onActionUpdate((e: GestureEvent) => {
              this.updateByLocalX(e.fingerList[0].localX)
            }),
          TapGesture()
            .onAction((e: GestureEvent) => {
              this.updateByLocalX(e.fingerList[0].localX)
            })
        )
      )
    }
    .width('100%')
    .height(this.barH())
    .onAreaChange((o: Area, n: Area) => {
      this.trackW = Number(n.width)
    })
  }
}

// components/tear_drop_slider.ets
// Tear Drop Slider (ArkUI ArkTS) - no function props
// Usage: TearDropSlider({ value: $val, config: { ... } })

export interface TearDropSliderStyle {
  trackHeight?: number            // default 8
  trackRadius?: number            // default trackHeight/2
  activeTrackColor?: string       // default '#9E9E9E' (grey)
  inactiveTrackColor?: string     // default '#34A853' (green)
  trackPaddingX?: number          // default 14

  // thumb
  thumbActiveWidth?: number       // default 50
  thumbInactiveWidth?: number     // default 40 (not used unless you want press-state)
  thumbFillColor?: string         // default '#8B05BF'
  thumbStrokeColor?: string       // default '' (disabled)
  thumbStrokeWidth?: number       // default 2
  thumbShadowColor?: string       // default 'rgba(0,0,0,0.35)'
  thumbElevation?: number         // default 10 (shadow blur)

  thumbText?: string              // default '< >'
  thumbTextColor?: string         // default '#9966CC'
  thumbTextSize?: number          // default 14

  // layout
  height?: number                 // overall component height (default 70)
  thumbYOffset?: number           // moves thumb down relative to track (default 10)
}

export interface TearDropSliderConfig {
  min?: number          // default 0
  max?: number          // default 100
  divisions?: number    // default 25 (snap). set 0/undefined for continuous
  style?: TearDropSliderStyle
}

@Component
export struct TearDropSlider {
  @Link value: number
  @Prop config?: TearDropSliderConfig

  // layout measured
  @State private sliderW: Length = 0
  @State private sliderH: Length = 0

  // thumb drag state
  @State private isDragging: boolean = false

  private ctx: CanvasRenderingContext2D = new CanvasRenderingContext2D()

  aboutToAppear() {
    // clamp initial
    this.value = this.clamp(this.value)
  }

  build() {
    // Outer: full width
    Column() {
      // ✅ Inner padded area = track + canvas + gesture share SAME width
      Stack() {
        // --- TRACK: inactive (full) ---
        Column() { }
        .width('100%')
        .height(this.trackHeight())
        .backgroundColor(this.inactiveTrackColor())
        .borderRadius(this.trackRadius())
        .position({ x: 0, y: (this.hheight() - this.trackHeight()) / 2 })

        // --- TRACK: active (left part) ---
        Column() { }
        .width(this.activeWidthPx())
        .height(this.trackHeight())
        .backgroundColor(this.activeTrackColor())
        .borderRadius(this.trackRadius())
        .position({ x: 0, y: (this.hheight() - this.trackHeight()) / 2 })

        // --- CANVAS (thumb) ---
        Canvas(this.ctx)
          .width('100%')
          .height(this.hheight())
          .onReady(() => {
            this.redraw()
          })
          .onAreaChange((o: Area, n: Area) => {
            // ✅ measure REAL padded width here
            this.sliderW = n.width
            this.sliderH = n.height
            this.redraw()
          })

        // --- GESTURE LAYER ---
        Column() { }
        .width('100%')
        .height(this.hheight())
        .opacity(0.001)
        .gesture(
          GestureGroup(GestureMode.Exclusive,
            PanGesture({ direction: PanDirection.Horizontal })
              .onActionStart((e: GestureEvent) => {
                this.isDragging = true
                this.updateByGlobalX(e.fingerList[0].globalX)
              })
              .onActionUpdate((e: GestureEvent) => {
                this.updateByGlobalX(e.fingerList[0].globalX)
              })
              .onActionEnd(() => {
                this.isDragging = false
                this.value = this.snap(this.value)
                this.redraw()
              }),
            TapGesture()
              .onAction((e: GestureEvent) => {
                this.updateByGlobalX(e.fingerList[0].globalX)
                this.value = this.snap(this.value)
                this.redraw()
              })
          )
        )
      }
      .width('100%')
      .height(this.hheight())
      // ✅ padding is applied to the SAME container that measures width
      .padding({ left: this.trackPaddingX(), right: this.trackPaddingX() })
    }
    .width('100%')
    .height(this.hheight())
  }
  // =========================
  // Drawing
  // =========================

  private redraw(): void {
    const w: number = this.lenToNumber(this.sliderW)
    const h: number = this.lenToNumber(this.sliderH)
    if (w <= 0 || h <= 0) return

    const ctx: CanvasRenderingContext2D = this.ctx
    ctx.clearRect(0, 0, w, h)

    // thumb center X in local coords (inside padded area)
    const cx: number = this.thumbCenterX()
    const trackY: number = (this.hheight() - this.trackHeight()) / 2
    const thumbW: number = this.thumbWidth()
    const thumbH: number = this.thumbWidth() // keep square base like Flutter

    // place teardrop with its top near the track and body below
    const x0: number = cx - thumbW / 2
    let y0: number = trackY + this.thumbYOffset()

    // ✅ prevent clipping (keeps teardrop fully visible)
    if (y0 < 0) y0 = 0
    const maxY: number = h - thumbH - 2
    if (y0 > maxY) y0 = maxY    // shadow
    ctx.save()
    ctx.shadowColor = this.thumbShadowColor()
    ctx.shadowBlur = this.thumbElevation()
    ctx.shadowOffsetX = 0
    ctx.shadowOffsetY = 6

    // draw teardrop path (normalized flutter path)
    this.drawTeardropPath(ctx, x0, y0, thumbW, thumbH)

    // fill
    ctx.fillStyle = this.thumbFillColor()
    ctx.fill()

    // optional stroke
    const sc: string = this.thumbStrokeColor()
    if (sc.length > 0 && this.thumbStrokeWidth() > 0) {
      ctx.lineWidth = this.thumbStrokeWidth()
      ctx.strokeStyle = sc
      ctx.stroke()
    }

    ctx.restore()

    // text inside
    const t: string = this.thumbText()
    if (t.length > 0) {
      ctx.save()
      ctx.fillStyle = this.thumbTextColor()
      ctx.font = `${this.thumbTextSize()}px sans-serif`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      // Flutter offset was: center.dy + size.width/1.8 (below center)
      const tx: number = cx
      const ty: number = y0 + thumbH * 0.70
      ctx.fillText(t, tx, ty)
      ctx.restore()
    }
  }

  private drawTeardropPath(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number): void {
    // This is a direct port of your Flutter Path (path_0) using normalized points.
    // Coordinates are fractions of w/h.
    ctx.beginPath()
    ctx.moveTo(x + w * 0.6824492, y + h * 0.2545195)

    ctx.bezierCurveTo(
      x + w * 0.6036973, y + h * 0.1315527,
      x + w * 0.5238008, y + h * 0.03013477,
      x + w * 0.5230039, y + h * 0.02912305
    )

    ctx.lineTo(x + w * 0.4999980, y + h * 0.0)
    ctx.lineTo(x + w * 0.4769941, y + h * 0.02912500)

    ctx.bezierCurveTo(
      x + w * 0.4761973, y + h * 0.03013477,
      x + w * 0.3963008, y + h * 0.1315527,
      x + w * 0.3175488, y + h * 0.2545215
    )

    ctx.bezierCurveTo(
      x + w * 0.2097910, y + h * 0.4227734,
      x + w * 0.1551562, y + h * 0.5501699,
      x + w * 0.1551562, y + h * 0.6331719
    )

    ctx.bezierCurveTo(
      x + w * 0.1551562, y + h * 0.8354414,
      x + w * 0.3098516, y + h * 1.0,
      x + w * 0.5000000, y + h * 1.0
    )

    ctx.bezierCurveTo(
      x + w * 0.6901484, y + h * 1.0,
      x + w * 0.8448438, y + h * 0.8354414,
      x + w * 0.8448438, y + h * 0.6331719
    )

    ctx.bezierCurveTo(
      x + w * 0.8448418, y + h * 0.5501699,
      x + w * 0.7902070, y + h * 0.4227734,
      x + w * 0.6824492, y + h * 0.2545195
    )

    ctx.closePath()
  }

  // =========================
  // Value math
  // =========================

  private updateByGlobalX(globalX: number): void {
    // In this simple version, globalX is close enough because our component is full width.
    // If you embed in a smaller container, you can switch to localX if needed.
    const w: number = this.lenToNumber(this.sliderW)
    if (w <= 0) return

    // Convert globalX roughly to localX using padding only
    // We'll map x in [0..w] (inside component bounds).
    let localX: number = globalX // may already be local-ish in many cases
    // clamp localX in [0..w]
    if (localX < 0) localX = 0
    if (localX > w) localX = w

    const min: number = this.min()
    const max: number = this.max()
    const ratio: number = this.clamp01(localX / w) // ✅ 0..1 gerçek değer aralığı
    const raw: number = min + ratio * (max - min)

    this.value = this.snap(raw)
    this.redraw()
  }

  private snap(v: number): number {
    const div: number = this.divisions()
    if (div <= 0) return this.clamp(v)
    const min: number = this.min()
    const max: number = this.max()
    const step: number = (max - min) / div
    const snapped: number = Math.round((v - min) / step) * step + min
    return this.clamp(snapped)
  }

  private clamp(v: number): number {
    const min: number = this.min()
    const max: number = this.max()
    if (v < min) return min
    if (v > max) return max
    return v
  }

  private clamp01(v: number): number {
    if (v < 0) return 0
    if (v > 1) return 1
    return v
  }

  private valueRatio(): number {
    const min: number = this.min()
    const max: number = this.max()
    const denom: number = (max - min)
    if (denom <= 0) return 0
    return this.clamp01((this.value - min) / denom)
  }

  private activeWidthPx(): number {
    const w: number = this.lenToNumber(this.sliderW)
    if (w <= 0) return 0
    return w * this.valueRatio()
  }

  private thumbCenterX(): number {
    const w: number = this.lenToNumber(this.sliderW)
    if (w <= 0) return 0

    const cx: number = w * this.valueRatio()
    const half: number = this.thumbWidth() / 2

    if (cx < half) return half
    if (cx > w - half) return w - half
    return cx
  }

  // =========================
  // Defaults / style getters
  // =========================

  private cfg(): TearDropSliderConfig { return this.config ?? {} }
  private st(): TearDropSliderStyle { return this.cfg().style ?? {} }

  private min(): number { return this.cfg().min ?? 0 }
  private max(): number { return this.cfg().max ?? 100 }
  private divisions(): number { return this.cfg().divisions ?? 25 }

  private hheight(): number { return this.st().height ?? 70 }
  private trackHeight(): number { return this.st().trackHeight ?? 8 }
  private trackRadius(): number { return this.st().trackRadius ?? (this.trackHeight() / 2) }
  private trackPaddingX(): number { return this.st().trackPaddingX ?? 14 }

  private activeTrackColor(): string { return this.st().activeTrackColor ?? '#9E9E9E' }
  private inactiveTrackColor(): string { return this.st().inactiveTrackColor ?? '#34A853' }

  private thumbActiveWidth(): number { return this.st().thumbActiveWidth ?? 50 }
  private thumbInactiveWidth(): number { return this.st().thumbInactiveWidth ?? 40 }
  private thumbWidth(): number {
    // no animation; use active width while dragging, else inactive (optional)
    return this.isDragging ? this.thumbActiveWidth() : this.thumbInactiveWidth()
  }

  private thumbFillColor(): string { return this.st().thumbFillColor ?? '#8B05BF' }
  private thumbStrokeColor(): string { return this.st().thumbStrokeColor ?? '' }
  private thumbStrokeWidth(): number { return this.st().thumbStrokeWidth ?? 2 }
  private thumbShadowColor(): string { return this.st().thumbShadowColor ?? 'rgba(0,0,0,0.35)' }
  private thumbElevation(): number { return this.st().thumbElevation ?? 10 }

  private thumbText(): string { return this.st().thumbText ?? '< >' }
  private thumbTextColor(): string { return this.st().thumbTextColor ?? '#9966CC' }
  private thumbTextSize(): number { return this.st().thumbTextSize ?? 14 }

  private thumbYOffset(): number { return this.st().thumbYOffset ?? 10 }

  private lenToNumber(v: Length): number {
    if (typeof v === 'number') return v
    if (typeof v === 'string') {
      const n: number = parseFloat(v)
      return isNaN(n) ? 0 : n
    }
    return 0
  }
}

export interface SliderFb4Style {
  trackHeight?: number
  thumbRadius?: number
  widthPadding?: number
  barHeight?: number

  primaryColor?: string         // active track
  thumbBgColor?: string         // thumb background (white)
  inactiveAlpha?: number        // inactive track alpha

  accentColor?: string          // active tick color (flutter: accentColor)
  divisionColor?: string        // inactive tick color (flutter: divisionColor)

  tickRadius?: number           // dot radius
  tickGapScale?: number         // spacing adjust (1 = normal)
  valueFontSize?: number
  valueFontWeight?: number
}

export interface SliderFb4Config {
  min: number
  max: number
  divisions: number
  style?: SliderFb4Style
}

function clamp01(v: number): number {
  if (v < 0) return 0
  if (v > 1) return 1
  return v
}

function clamp(v: number, minV: number, maxV: number): number {
  if (v < minV) return minV
  if (v > maxV) return maxV
  return v
}

function withAlpha(color: string, alpha01: number): string {
  const a: number = Math.round(clamp01(alpha01) * 255)
  const aHex: string = a.toString(16).padStart(2, '0')
  if (color.startsWith('#') && color.length === 7) {
    return `#${aHex}${color.substring(1)}`
  }
  if (color.startsWith('#') && color.length === 9) {
    return `#${aHex}${color.substring(3)}`
  }
  return color
}

@Component
export struct SliderFb4Steps {
  @Link value: number
  @Prop config: SliderFb4Config

  @State private trackW: number = 0

  // getters
  private min(): number { return this.config.min }
  private max(): number { return this.config.max }
  private divisions(): number { return this.config.divisions }

  private primary(): string { return this.config.style?.primaryColor ?? '#3F51B5' }
  private inactiveAlpha(): number { return this.config.style?.inactiveAlpha ?? 0.18 }

  private accent(): string { return this.config.style?.accentColor ?? '#FFFFFF' }
  private divisionColor(): string { return this.config.style?.divisionColor ?? '#3F51B5' }

  private trackHeight(): number { return this.config.style?.trackHeight ?? 4 }
  private thumbR(): number { return this.config.style?.thumbRadius ?? 20 }
  private padX(): number { return this.config.style?.widthPadding ?? 18 }
  private barH(): number { return this.config.style?.barHeight ?? 80 }

  private thumbBg(): string { return this.config.style?.thumbBgColor ?? '#FFFFFF' }

  private tickR(): number { return this.config.style?.tickRadius ?? 2.2 }
  private tickGapScale(): number { return this.config.style?.tickGapScale ?? 1 }

  private valueFontSize(): number { return this.config.style?.valueFontSize ?? 18 }
  private valueFontWeight(): number { return this.config.style?.valueFontWeight ?? 700 }

  private ratio(): number {
    if (this.max() <= this.min()) return 0
    return clamp01((this.value - this.min()) / (this.max() - this.min()))
  }

  private valueFromRatio(r: number): number {
    return this.min() + (this.max() - this.min()) * clamp01(r)
  }

  private snap(v: number): number {
    const div: number = this.divisions()
    if (div <= 0) return v
    const step: number = (this.max() - this.min()) / div
    const idx: number = Math.round((v - this.min()) / step)
    return this.min() + idx * step
  }

  private usableW(): number {
    const w: number = this.trackW - this.padX() * 2
    return w > 0 ? w : 0
  }

  private thumbCenterX(): number {
    const cx: number = this.padX() + this.ratio() * this.usableW()
    const minCx: number = this.padX() + this.thumbR()
    const maxCx: number = this.padX() + this.usableW() - this.thumbR()
    return clamp(cx, minCx, maxCx)
  }

  private thumbLeftX(): number {
    return this.thumbCenterX() - this.thumbR()
  }

  private updateByLocalX(localX: number): void {
    const w: number = this.usableW()
    if (w <= 1) return

    const x: number = clamp(localX - this.padX(), 0, w)
    const r: number = clamp01(x / w)

    let v: number = this.valueFromRatio(r)
    v = this.snap(v)
    this.value = clamp(v, this.min(), this.max())
  }

  private format(v: number): string {
    return Math.round(v).toString()
  }

  @Builder
  private TicksRow() {

    if (this.divisions() > 0) {

      Row() {
        ForEach(
          new Array<number>(this.divisions() + 1).fill(0).map((_, i) => i),
          (i: number) => {

            Row() { }
            .width(this.tickR() * 2)
            .height(this.tickR() * 2)
            .borderRadius(this.tickR())
            .backgroundColor(
              i <= Math.round(this.ratio() * this.divisions())
                ? this.accent()
                : this.divisionColor()
            )

          },
          (i: number) => i.toString()
        )
      }
      .width(this.usableW())
      .justifyContent(FlexAlign.SpaceBetween)
      .position({
        x: this.padX(),
        y: (this.barH() - this.trackHeight()) / 2 +
          (this.trackHeight() / 2) -
        this.tickR()
      })

    }

  }

  build() {
    Stack() {

      // Inactive track
      Row() { }
      .width(this.usableW())
      .height(this.trackHeight())
      .backgroundColor(withAlpha(this.primary(), this.inactiveAlpha()))
      .borderRadius(this.trackHeight() / 2)
      .position({ x: this.padX(), y: (this.barH() - this.trackHeight()) / 2 })

      // Active track
      Row() { }
      .width(this.ratio() * this.usableW())
      .height(this.trackHeight())
      .backgroundColor(this.primary())
      .borderRadius(this.trackHeight() / 2)
      .position({ x: this.padX(), y: (this.barH() - this.trackHeight()) / 2 })

      // Tick dots
      this.TicksRow()

      // Thumb (value inside)
      Stack() {
        Row() { }
        .width(this.thumbR() * 2)
        .height(this.thumbR() * 2)
        .backgroundColor(this.thumbBg())
        .borderRadius(this.thumbR())

        Text(this.format(this.value))
          .fontSize(this.valueFontSize())
          .fontWeight(this.valueFontWeight())
          .fontColor(this.primary())
          .textAlign(TextAlign.Center)
      }
      .width(this.thumbR() * 2)
      .height(this.thumbR() * 2)
      .position({
        x: this.thumbLeftX(),
        y: (this.barH() - this.trackHeight()) / 2 - (this.thumbR() * 2 - this.trackHeight()) / 2
      })

      // Gesture layer
      Row() { }
      .width('100%')
      .height('100%')
      .opacity(0.001)
      .gesture(
        GestureGroup(GestureMode.Exclusive,
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart((e: GestureEvent) => {
              this.updateByLocalX(e.fingerList[0].localX)
            })
            .onActionUpdate((e: GestureEvent) => {
              this.updateByLocalX(e.fingerList[0].localX)
            }),
          TapGesture()
            .onAction((e: GestureEvent) => {
              this.updateByLocalX(e.fingerList[0].localX)
            })
        )
      )
    }
    .width('100%')
    .height(this.barH())
    .onAreaChange((o: Area, n: Area) => {
      this.trackW = Number(n.width)
    })
  }
}

// components/curved_nav_static.ets
// Static curved bottom bar (no animation) + selectable items + dot indicator
// 2 left + center floating + 2 right
// No function props. Uses @Link selectedIndex.

export interface StaticCurvedNavItem {
  key: string
  icon: Resource
  index: number // 0..3 (left0,left1,right0,right1)
}

export interface StaticCurvedNavStyle {
  hheight?: number
  painterhheight?: number
  topY?: number

  barColor?: string
  bbackgroundColor?: string

  iconSize?: number
  iconBaseOffsetY?: number

  // selection indicator
  showDot?: boolean
  dotSize?: number
  dotOffsetY?: number
  dotColor?: string

  // notch geometry
  notchWidthFactor?: number
  notchSideGap?: number
  notchDepthFactor?: number

  // center button
  centerSize?: number
  centerButtonBg?: string
  centerIcon?: Resource
  centerIconSize?: number
  centerBottomOffset?: number

  // selected colors
  selectedIconColor?: string // optional (if you later add tint logic)
}

export interface StaticCurvedNavConfig {
  items?: StaticCurvedNavItem[]
  style?: StaticCurvedNavStyle

  // which index should center button set when tapped
  centerIndex?: number // default 2 (or 4 if you want separate page)
}

@Component
export struct StaticCurvedBottomNav {
  @Link selectedIndex: number
  @Prop config?: StaticCurvedNavConfig

  @State private rowWidth: Length = 0
  @State private canvasW: Length = 0
  @State private canvasH: Length = 0

  private ctx: CanvasRenderingContext2D = new CanvasRenderingContext2D()

  aboutToAppear() {
    // clamp initial
    this.selectedIndex = this.clampIndex(this.selectedIndex)
  }

  build() {
    Stack({ alignContent: Alignment.Bottom }) {

      Column() { }
      .width('100%')
      .height(this.hheight())
      .backgroundColor(this.bbackgroundColor())

      Canvas(this.ctx)
        .width('100%')
        .height(this.painterhheight())
        .position({ x: 0, y: this.hheight() - this.painterhheight() })
        .onReady(() => this.drawBar())
        .onAreaChange((o: Area, n: Area) => {
          this.canvasW = n.width
          this.canvasH = n.height
          this.drawBar()
        })

      Row() {
        this.IconCell(this.items()[0])
        this.IconCell(this.items()[1])

        Column() { }
        .width(this.centerCellWidth())
        .height(1)

        this.IconCell(this.items()[2])
        this.IconCell(this.items()[3])
      }
      .width('100%')
      .height(this.hheight())
      .alignItems(VerticalAlign.Center)
      .onAreaChange((o: Area, n: Area) => {
        this.rowWidth = n.width
        this.drawBar()
      })

      // center floating
      Stack() { this.CenterButton() }
      .width(this.centerCellWidth())
      .height(this.painterhheight())
      .position({
        x: (this.totalWidth() - this.centerCellWidth()) / 2,
        y: this.hheight() - this.painterhheight() + this.centerBottomOffset()
      })
    }
    .width('100%')
    .height(this.hheight())
    .clip(false)
  }

  // ---------- UI ----------

  @Builder
  private IconCell(item: StaticCurvedNavItem) {
    // A single "slot" column: icon + optional dot
    Column() {
      // icon
      Image(item.icon)
        .width(this.iconSize())
        .height(this.iconSize())
        .objectFit(ImageFit.Contain)

      // dot (selected indicator)
      if (this.showDot() && this.isSelected(item.index)) {
        Column() { }
        .width(this.dotSize())
        .height(this.dotSize())
        .borderRadius(this.dotSize() / 2)
        .backgroundColor(this.dotColor())
        .margin({ top: this.dotOffsetY() })
      } else {
        // keep layout stable
        Column() { }
        .width(this.dotSize())
        .height(this.dotSize())
        .opacity(0)
        .margin({ top: this.dotOffsetY() })
      }
    }
    .width(this.sideCellWidth())
    .height(this.hheight())
    .justifyContent(FlexAlign.Center)
    // push whole block down into bar (so icons are not half outside)
    .translate({ x: 0, y: this.iconBaseOffsetY() })
    .onClick(() => {
      this.selectedIndex = this.clampIndex(item.index)
    })
  }

  @Builder
  private CenterButton() {
    Stack() {
      Column() { }
      .width(this.centerSize())
      .height(this.centerSize())
      .backgroundColor(this.centerButtonBg())
      .borderRadius(this.centerSize() / 2)

      Image(this.centerIcon())
        .width(this.centerIconSize())
        .height(this.centerIconSize())
        .objectFit(ImageFit.Contain)
    }
    .width(this.centerSize())
    .height(this.centerSize())
    .align(Alignment.Center)
    .onClick(() => {
      this.selectedIndex = this.clampIndex(this.centerIndex())
    })
  }

  // ---------- Painter (smooth center notch) ----------

  private drawBar() {
    const w: number = this.lenToNumber(this.canvasW)
    const h: number = this.lenToNumber(this.canvasH)
    if (w <= 0 || h <= 0) return

    const ctx: CanvasRenderingContext2D = this.ctx
    ctx.clearRect(0, 0, w, h)

    const s: number = this.notchWidthFactor()
    const gap: number = this.notchSideGap()
    const depth: number = this.notchDepthFactor()
    const loc: number = 0.5 - (s / 2)

    ctx.save()
    ctx.beginPath()

    ctx.moveTo(0, this.topY())
    ctx.lineTo((loc - gap) * w, this.topY())

    ctx.bezierCurveTo(
      (loc + s * 0.20) * w, h * 0.05,
      loc * w,              h * depth,
      (loc + s * 0.50) * w, h * depth
    )

    ctx.bezierCurveTo(
      (loc + s) * w,              h * depth,
      (loc + s - s * 0.20) * w,   h * 0.05,
      (loc + s + gap) * w,        this.topY()
    )

    ctx.lineTo(w, this.topY())
    ctx.lineTo(w, h)
    ctx.lineTo(0, h)
    ctx.closePath()

    ctx.fillStyle = this.barColor()
    ctx.fill()

    ctx.restore()
  }

  // ---------- selection helpers ----------

  private isSelected(i: number): boolean {
    return this.selectedIndex === i
  }

  private clampIndex(i: number): number {
    // we allow 0..3 by default; if you set centerIndex=4, clamp to 4 too
    const maxIndex: number = Math.max(3, this.centerIndex())
    if (i < 0) return 0
    if (i > maxIndex) return maxIndex
    return i
  }

  // ---------- layout helpers ----------

  private totalWidth(): number {
    const rw: number = this.lenToNumber(this.rowWidth)
    if (rw > 0) return rw
    return this.lenToNumber(this.canvasW)
  }

  private centerCellWidth(): number {
    const w: number = this.totalWidth()
    return w <= 0 ? 0 : (w / 5)
  }

  private sideCellWidth(): number {
    const w: number = this.totalWidth()
    return w <= 0 ? 0 : (w / 5)
  }

  // ---------- defaults / config ----------

  private cfg(): StaticCurvedNavConfig { return this.config ?? {} }
  private st(): StaticCurvedNavStyle { return this.cfg().style ?? {} }

  private items(): StaticCurvedNavItem[] {
    const its: StaticCurvedNavItem[] | undefined = this.cfg().items
    if (its && its.length >= 4) return its.slice(0, 4)
    return [
      { key: 'left0', icon: $r('app.media.startIcon'), index: 0 },
      { key: 'left1', icon: $r('app.media.startIcon'), index: 1 },
      { key: 'right0', icon: $r('app.media.startIcon'), index: 2 },
      { key: 'right1', icon: $r('app.media.startIcon'), index: 3 }
    ]
