          title: 'Download in progress',
          text: `Downloading... ${progress}%`,
          additionalText: ''
        }
      },
      template: {
        name: 'downloadTemplate',
        data: {
          title: 'Download Progress',
          fileName: 'file.zip',
          progressValue: progress
